tool_schemas.implementation:
def jira_get_issue(connection_id, issue_key=None, issue_id=None, expand=None, fields=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    tool_name = "jira_get_issue"

    def _new_op_id():
        return "op_" + uuid.uuid4().hex

    def _log_op(tool_operations, status, http_status=None, error_code=None, error_message=None,
                response_summary=None, affected_domain=None, affected_entity_type=None, affected_external_ids=None,
                started_at=None, finished_at=None):
        op = {
            "id": _new_op_id(),
            "connection_id": connection_id,
            "tool_name": tool_name,
            "request": {
                "connection_id": connection_id,
                "issue_key": issue_key,
                "issue_id": issue_id,
                "expand": expand,
                "fields": fields
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": affected_domain,
            "affected_entity_type": affected_entity_type,
            "affected_external_ids": affected_external_ids,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now
        }
        tool_operations.append(op)
        _save("tool_operations.json", tool_operations)

    def _validate_expand(exp):
        allowed = {"renderedFields", "names", "schema", "transitions", "operations", "editmeta", "changelog"}
        if exp is None:
            return True, None
        if not isinstance(exp, list) or any((not isinstance(x, str) or x not in allowed) for x in exp):
            return False, "expand contains unsupported values"
        return True, None

    def _validate_fields(f):
        if f is None:
            return True, None
        if not isinstance(f, list) or any(not isinstance(x, str) or not x.strip() for x in f):
            return False, "fields must be an array of non-empty strings"
        return True, None

    def _select_fields_from_raw(raw_obj, field_list):
        if raw_obj is None:
            return None
        if field_list is None:
            return raw_obj
        # Jira issues typically have {"fields": {...}}; return a pruned version but keep top-level identifiers.
        out = {}
        for k in ("id", "key", "self"):
            if isinstance(raw_obj, dict) and k in raw_obj:
                out[k] = raw_obj.get(k)
        if isinstance(raw_obj, dict) and "fields" in raw_obj and isinstance(raw_obj["fields"], dict):
            out_fields = {}
            for f in field_list:
                if f in raw_obj["fields"]:
                    out_fields[f] = raw_obj["fields"].get(f)
            out["fields"] = out_fields
        else:
            # If raw doesn't follow expected shape, just return it unchanged.
            out = raw_obj
        return out

    # Input validation
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id or ""):
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message="connection_id is malformed", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "connection_id is malformed")

    if (issue_key is None and issue_id is None) or (issue_key is not None and issue_id is not None):
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message="Provide exactly one of issue_key or issue_id", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "Provide exactly one of issue_key or issue_id")

    if issue_key is not None and (not isinstance(issue_key, str) or not issue_key.strip()):
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message="issue_key must be a non-empty string", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "issue_key must be a non-empty string")

    if issue_id is not None and (not isinstance(issue_id, str) or not issue_id.strip()):
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message="issue_id must be a non-empty string", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "issue_id must be a non-empty string")

    ok, msg = _validate_expand(expand)
    if not ok:
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message=msg, started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", msg)

    ok, msg = _validate_fields(fields)
    if not ok:
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message=msg, started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", msg)

    # Auth / connection scoping: must be active
    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    tool_operations = _load("tool_operations.json")

    if not conn or conn.get("status") != "active":
        _log_op(tool_operations, status="failed", http_status=401, error_code="unauthorized",
                error_message="No active connection available for this request", started_at=now, finished_at=now)
        return _err("UNAUTHORIZED", "No active connection available for this request")

    # Rate limit/quota enforcement (remote call budget + concurrent running)
    one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    running = [op for op in tool_operations if op.get("connection_id") == connection_id and op.get("status") == "running"]
    if len(running) >= 10:
        _log_op(tool_operations, status="failed", http_status=429, error_code="rate_limited",
                error_message="Too many concurrent operations", started_at=now, finished_at=now)
        return _err("RATE_LIMIT", "Too many concurrent operations", retry_after_seconds=60)

    # For jira_get_issue, treat a cache miss as requiring a remote call.
    jira_entities = _load("jira_entities.json")

    issue_row = None
    if issue_id is not None:
        issue_row = next((e for e in jira_entities
                          if e.get("connection_id") == connection_id and e.get("entity_type") == "issue"
                          and e.get("external_id") == issue_id), None)
    else:
        issue_row = next((e for e in jira_entities
                          if e.get("connection_id") == connection_id and e.get("entity_type") == "issue"
                          and e.get("key") == issue_key), None)

    # Enforce remote calls per minute only if we'd need remote.
    if issue_row is None:
        recent_remote = [
            op for op in tool_operations
            if op.get("connection_id") == connection_id
            and op.get("started_at") is not None
            and op.get("started_at") >= one_min_ago
            and op.get("tool_name") in (
                "jira_get_issue", "jira_search", "jira_get_project_issues", "jira_get_epic_issues",
                "jira_get_transitions", "jira_get_worklog", "jira_download_attachments",
                "jira_get_agile_boards", "jira_get_board_issues", "jira_get_sprints_from_board",
                "jira_get_sprint_issues", "jira_update_sprint", "jira_create_issue", "jira_batch_create_issues",
                "jira_update_issue", "jira_delete_issue", "jira_add_comment", "jira_add_worklog",
                "jira_link_to_epic", "jira_create_issue_link", "jira_remove_issue_link",
                "jira_transition_issue", "jira_search_fields",
                "confluence_search", "confluence_get_page", "confluence_get_page_children",
                "confluence_get_page_ancestors", "confluence_get_comments",
                "confluence_create_page", "confluence_update_page", "confluence_delete_page"
            )
        ]
        # count remote attempts as succeeded/failed (not queued/cancelled), approximating actual remote call usage
        remote_count = sum(1 for op in recent_remote if op.get("status") in ("succeeded", "failed"))
        if remote_count >= 60:
            _log_op(tool_operations, status="failed", http_status=429, error_code="rate_limited",
                    error_message="Remote API rate limit exceeded", started_at=now, finished_at=now)
            return _err("RATE_LIMIT", "Remote API rate limit exceeded", retry_after_seconds=60)

        # Offline backend cannot actually fetch remote; record failed operation
        _log_op(tool_operations, status="failed", http_status=503, error_code="remote_unavailable",
                error_message="Cache miss and remote fetch is unavailable in offline mode",
                affected_domain="jira", affected_entity_type="issue",
                affected_external_ids=[issue_id] if issue_id is not None else None,
                started_at=now, finished_at=now)
        return _err("NOT_FOUND", "Issue not found in cache and remote fetch unavailable")

    # Return from cache; log succeeded
    raw_obj = issue_row.get("raw")
    response_issue = _select_fields_from_raw(raw_obj, fields)

    # Include transitions etc. only if present in raw; expand is validated but not executed remotely here
    if expand is not None and isinstance(response_issue, dict) and isinstance(raw_obj, dict):
        # If raw already has sections, keep as-is; otherwise nothing to add.
        pass

    _log_op(tool_operations, status="succeeded", http_status=200, error_code=None, error_message=None,
            response_summary={"source": "cache", "issue_external_id": issue_row.get("external_id"), "issue_key": issue_row.get("key")},
            affected_domain="jira", affected_entity_type="issue",
            affected_external_ids=[issue_row.get("external_id")],
            started_at=now, finished_at=now)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "issue": response_issue,
        "meta": {
            "connection_id": connection_id,
            "source": "cache",
            "latency_ms": latency_ms
        }
    }

def jira_get_project_issues(connection_id, project_key, jql=None, fields=None, expand=None, start_at=None, max_results=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"
    tool_name = "jira_get_project_issues"

    def _new_op_id():
        return "op_" + uuid.uuid4().hex

    def _log_op(tool_operations, status, http_status=None, error_code=None, error_message=None,
                response_summary=None, affected_domain=None, affected_entity_type=None, affected_external_ids=None,
                started_at=None, finished_at=None):
        op = {
            "id": _new_op_id(),
            "connection_id": connection_id,
            "tool_name": tool_name,
            "request": {
                "connection_id": connection_id,
                "project_key": project_key,
                "jql": jql,
                "fields": fields,
                "expand": expand,
                "start_at": start_at,
                "max_results": max_results
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": affected_domain,
            "affected_entity_type": affected_entity_type,
            "affected_external_ids": affected_external_ids,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now
        }
        tool_operations.append(op)
        _save("tool_operations.json", tool_operations)

    def _validate_expand(exp):
        allowed = {"renderedFields", "names", "schema", "transitions", "operations", "editmeta", "changelog"}
        if exp is None:
            return True, None
        if not isinstance(exp, list) or any((not isinstance(x, str) or x not in allowed) for x in exp):
            return False, "expand contains unsupported values"
        return True, None

    def _validate_fields(f):
        if f is None:
            return True, None
        if not isinstance(f, list) or any(not isinstance(x, str) or not x.strip() for x in f):
            return False, "fields must be an array of non-empty strings"
        return True, None

    def _select_fields_from_raw(raw_obj, field_list):
        if raw_obj is None:
            return None
        if field_list is None:
            return raw_obj
        if isinstance(raw_obj, dict) and isinstance(raw_obj.get("fields"), dict):
            out = {}
            for k in ("id", "key", "self"):
                if k in raw_obj:
                    out[k] = raw_obj.get(k)
            out_fields = {}
            for f in field_list:
                if f in raw_obj["fields"]:
                    out_fields[f] = raw_obj["fields"].get(f)
            out["fields"] = out_fields
            return out
        return raw_obj

    # Validation
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id or ""):
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message="connection_id is malformed", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "connection_id is malformed")

    if not isinstance(project_key, str) or not re.match(r"^[A-Z][A-Z0-9_]+$", project_key.strip().upper()):
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message="project_key is missing/invalid", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "project_key is missing/invalid")

    if jql is not None and (not isinstance(jql, str) or not jql.strip()):
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message="jql must be a non-empty string when provided", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "jql must be a non-empty string when provided")

    if start_at is None:
        start_at = 0
    if max_results is None:
        max_results = 50
    if not isinstance(start_at, int) or start_at < 0:
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message="start_at out of range", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "start_at out of range")
    if not isinstance(max_results, int) or max_results < 1 or max_results > 100:
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message="max_results out of range", started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", "max_results out of range")

    ok, msg = _validate_expand(expand)
    if not ok:
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message=msg, started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", msg)

    ok, msg = _validate_fields(fields)
    if not ok:
        tool_operations = _load("tool_operations.json")
        _log_op(tool_operations, status="failed", http_status=400, error_code="validation_error",
                error_message=msg, started_at=now, finished_at=now)
        return _err("VALIDATION_ERROR", msg)

    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    tool_operations = _load("tool_operations.json")

    if not conn or conn.get("status") != "active":
        _log_op(tool_operations, status="failed", http_status=401, error_code="unauthorized",
                error_message="No active connection available for this request", started_at=now, finished_at=now)
        return _err("UNAUTHORIZED", "No active connection available for this request")

    running = [op for op in tool_operations if op.get("connection_id") == connection_id and op.get("status") == "running"]
    if len(running) >= 10:
        _log_op(tool_operations, status="failed", http_status=429, error_code="rate_limited",
                error_message="Too many concurrent operations", started_at=now, finished_at=now)
        return _err("RATE_LIMIT", "Too many concurrent operations", retry_after_seconds=60)

    # This tool is a remote search; enforce remote calls/min.
    one_min_ago = (now_dt - datetime.timedelta(seconds=60)).isoformat() + "Z"
    recent_remote = [
        op for op in tool_operations
        if op.get("connection_id") == connection_id
        and op.get("started_at") is not None
        and op.get("started_at") >= one_min_ago
        and op.get("tool_name") in (
            "jira_get_issue", "jira_search", "jira_get_project_issues", "jira_get_epic_issues",
            "jira_get_transitions", "jira_get_worklog", "jira_download_attachments",
            "jira_get_agile_boards", "jira_get_board_issues", "jira_get_sprints_from_board",
            "jira_get_sprint_issues", "jira_update_sprint", "jira_create_issue", "jira_batch_create_issues",
            "jira_update_issue", "jira_delete_issue", "jira_add_comment", "jira_add_worklog",
            "jira_link_to_epic", "jira_create_issue_link", "jira_remove_issue_link",
            "jira_transition_issue", "jira_search_fields",
            "confluence_search", "confluence_get_page", "confluence_get_page_children",
            "confluence_get_page_ancestors", "confluence_get_comments",
            "confluence_create_page", "confluence_update_page", "confluence_delete_page"
        )
    ]
    remote_count = sum(1 for op in recent_remote if op.get("status") in ("succeeded", "failed"))
    if remote_count >= 60:
        _log_op(tool_operations, status="failed", http_status=429, error_code="rate_limited",
                error_message="Remote API rate limit exceeded", started_at=now, finished_at=now)
        return _err("RATE_LIMIT", "Remote API rate limit exceeded", retry_after_seconds=60)

    # Offline fallback: filter cached active issues by project_key (by issue key prefix or raw.fields.project.key)
    pk = project_key.strip().upper()
    jira_entities = _load("jira_entities.json")
    issues = [e for e in jira_entities if e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("status") == "active"]

    proj_issues = []
    for e in issues:
        k = (e.get("key") or "").upper()
        raw = e.get("raw") or {}
        raw_pk = ""
        try:
            raw_pk = ((raw.get("fields") or {}).get("project") or {}).get("key") or ""
        except Exception:
            raw_pk = ""
        if (k.startswith(pk + "-")) or (isinstance(raw_pk, str) and raw_pk.upper() == pk):
            proj_issues.append(e)

    # Apply optional additional clause extremely conservatively (no real JQL parsing); only support "AND key = X"
    if jql:
        m_key = re.search(r"\bkey\s*=\s*([A-Z][A-Z0-9]+-\d+)\b", jql, re.IGNORECASE)
        if m_key:
            kk = m_key.group(1).upper()
            proj_issues = [e for e in proj_issues if (e.get("key") or "").upper() == kk]
        else:
            # Unknown clause -> return empty (safer than pretending).
            proj_issues = []

    total = len(proj_issues)
    page = proj_issues[start_at:start_at + max_results]
    issue_payloads = []
    affected_ids = []
    for e in page:
        issue_payloads.append(_select_fields_from_raw(e.get("raw"), fields))
        affected_ids.append(e.get("external_id"))

    executed_jql = f"project = {pk}"
    if jql:
        executed_jql = executed_jql + " " + jql.strip()

    _log_op(
        tool_operations,
        status="succeeded",
        http_status=200,
        response_summary={"jql": executed_jql, "total": total, "returned": len(page), "source": "cache_fallback"},
        affected_domain="jira",
        affected_entity_type="issue",
        affected_external_ids=affected_ids,
        started_at=now,
        finished_at=now
    )

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "startAt": start_at,
        "maxResults": max_results,
        "total": total,
        "issues": issue_payloads,
        "meta": {
            "connection_id": connection_id,
            "project_key": pk,
            "executed_jql": executed_jql,
            "source": "cache_fallback",
            "latency_ms": latency_ms
        }
    }

def jira_get_transitions(connection_id, issue_key=None, issue_id=None, expand=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "connection_id is malformed")
    has_key = issue_key is not None
    has_id = issue_id is not None
    if has_key == has_id:
        return _err("VALIDATION_ERROR", "Provide exactly one of issue_key or issue_id")
    if issue_key is not None and not isinstance(issue_key, str):
        return _err("VALIDATION_ERROR", "issue_key must be a string")
    if issue_id is not None and (not isinstance(issue_id, str) or not issue_id.strip()):
        return _err("VALIDATION_ERROR", "issue_id must be a non-empty string")
    if expand is not None:
        if not isinstance(expand, list) or any((not isinstance(x, str)) for x in expand):
            return _err("VALIDATION_ERROR", "expand must be an array of strings")
        allowed = {"transitions.fields"}
        bad = [x for x in expand if x not in allowed]
        if bad:
            return _err("VALIDATION_ERROR", "expand contains unsupported values", unsupported=bad)

    # Load store
    conns = _load("atlassian_connections.json")
    jira = _load("jira_entities.json")
    ops = _load("tool_operations.json")

    # Helper to log op
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        ts = int(time.time() * 1000)
        n = ts
        out = []
        while n:
            n, r = divmod(n, 36)
            out.append(alphabet[r])
        base = "".join(reversed(out or ["0"]))
        base = (base + "0" * 18)[:18]
        return f"{prefix}{base}"

    def _log(status, http_status=None, error_code=None, error_message=None, response_summary=None,
             affected_domain=None, affected_entity_type=None, affected_external_ids=None, started_at=None, finished_at=None):
        op_id = _new_id("atl_op_")
        row = {
            "id": op_id,
            "connection_id": connection_id,
            "tool_name": "jira_get_transitions",
            "request": {
                "connection_id": connection_id,
                "issue_key": issue_key,
                "issue_id": issue_id,
                "expand": expand
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": affected_domain,
            "affected_entity_type": affected_entity_type,
            "affected_external_ids": affected_external_ids,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    # Connection must be active
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        _log("failed", http_status=404, error_code="not_found", error_message="Connection not found",
             started_at=now, finished_at=now)
        return _err("NOT_FOUND", "Connection not found")
    if conn.get("status") != "active":
        _log("failed", http_status=401, error_code="unauthorized", error_message="Connection is not active",
             started_at=now, finished_at=now)
        return _err("UNAUTHORIZED", "Connection is not active")

    # Rate limits: concurrent running <=10 and remote calls <=60/min (we count this tool as a remote call)
    running = [o for o in ops if o.get("connection_id") == connection_id and o.get("status") == "running"]
    if len(running) >= 10:
        _log("failed", http_status=429, error_code="rate_limited", error_message="Too many concurrent operations",
             started_at=now, finished_at=now)
        return _err("RATE_LIMIT", "Too many concurrent operations")
    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0)
    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    recent = 0
    for o in ops:
        if o.get("connection_id") != connection_id:
            continue
        sa = _parse_dt(o.get("started_at"))
        if sa and sa >= cutoff:
            recent += 1
    if recent >= 60:
        _log("failed", http_status=429, error_code="rate_limited", error_message="Remote rate limit exceeded",
             started_at=now, finished_at=now)
        return _err("RATE_LIMIT", "Remote rate limit exceeded")

    # Create op as running
    started = now
    op_row = _log("running", started_at=started)

    # Resolve issue in cache by external_id or key
    issue = None
    if issue_id is not None:
        issue = next((e for e in jira if e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("external_id") == issue_id), None)
    else:
        issue = next((e for e in jira if e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("key") == issue_key), None)

    if not issue or issue.get("status") == "deleted":
        # For this offline backend, treat as not found (remote fetch not available)
        op_row["status"] = "failed"
        op_row["http_status"] = 404
        op_row["error_code"] = "not_found"
        op_row["error_message"] = "Issue not found"
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        _save("tool_operations.json", ops)
        return _err("NOT_FOUND", "Issue not found")

    raw = issue.get("raw") or {}
    transitions_payload = raw.get("transitions")
    # Provide a deterministic fallback if none is present, but do not invent transitions as remote truth.
    if not isinstance(transitions_payload, list):
        transitions_payload = []

    # Optionally include fields metadata if stored; if expand requested and fields missing, still return transitions.
    if expand and "transitions.fields" in expand:
        # Ensure each transition has "fields" key if available in raw
        # No-op if not present.
        pass

    # Update operation as succeeded; reflect transitions in operation log
    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_row["status"] = "succeeded"
    op_row["http_status"] = 200
    op_row["error_code"] = None
    op_row["error_message"] = None
    op_row["response_summary"] = {"transitions_count": len(transitions_payload), "issue_external_id": issue.get("external_id"), "issue_key": issue.get("key")}
    op_row["affected_domain"] = "jira"
    op_row["affected_entity_type"] = "issue"
    op_row["affected_external_ids"] = [issue.get("external_id")]
    op_row["finished_at"] = finished
    op_row["updated_at"] = finished
    _save("tool_operations.json", ops)

    return {
        "issue": {"id": issue.get("external_id"), "key": issue.get("key")},
        "transitions": transitions_payload,
        "expand": expand or [],
        "meta": {"operation_id": op_row["id"], "latency_ms": int((time.time() - t0) * 1000)}
    }

def jira_get_worklog(connection_id, issue_key=None, issue_id=None, start_at=None, max_results=None, started_after=None, started_before=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "connection_id is malformed")
    has_key = issue_key is not None
    has_id = issue_id is not None
    if has_key == has_id:
        return _err("VALIDATION_ERROR", "Provide exactly one of issue_key or issue_id")
    if start_at is None: start_at = 0
    if max_results is None: max_results = 50
    if not isinstance(start_at, int) or start_at < 0:
        return _err("VALIDATION_ERROR", "start_at must be an integer >= 0")
    if not isinstance(max_results, int) or max_results < 1 or max_results > 1000:
        return _err("VALIDATION_ERROR", "max_results must be an integer between 1 and 1000")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an ISO date-time string")
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            raise ValueError(f"{field} is not a valid date-time")

    try:
        dt_after = _parse_dt(started_after, "started_after")
        dt_before = _parse_dt(started_before, "started_before")
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))
    if dt_after and dt_before and dt_before < dt_after:
        return _err("VALIDATION_ERROR", "started_before must be >= started_after")

    # Load
    conns = _load("atlassian_connections.json")
    jira = _load("jira_entities.json")
    ops = _load("tool_operations.json")

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        ts = int(time.time() * 1000)
        n = ts
        out = []
        while n:
            n, r = divmod(n, 36)
            out.append(alphabet[r])
        base = "".join(reversed(out or ["0"]))
        base = (base + "0" * 18)[:18]
        return f"{prefix}{base}"

    def _log(status, http_status=None, error_code=None, error_message=None, response_summary=None,
             affected_domain=None, affected_entity_type=None, affected_external_ids=None, started_at=None, finished_at=None):
        op_id = _new_id("atl_op_")
        row = {
            "id": op_id,
            "connection_id": connection_id,
            "tool_name": "jira_get_worklog",
            "request": {
                "connection_id": connection_id,
                "issue_key": issue_key,
                "issue_id": issue_id,
                "start_at": start_at,
                "max_results": max_results,
                "started_after": started_after,
                "started_before": started_before
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": affected_domain,
            "affected_entity_type": affected_entity_type,
            "affected_external_ids": affected_external_ids,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    # Auth: connection must exist and be active
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        _log("failed", http_status=404, error_code="not_found", error_message="Connection not found",
             started_at=now, finished_at=now)
        return _err("NOT_FOUND", "Connection not found")
    if conn.get("status") != "active":
        _log("failed", http_status=401, error_code="unauthorized", error_message="Connection is not active",
             started_at=now, finished_at=now)
        return _err("UNAUTHORIZED", "Connection is not active")

    # Read-only tool still logs; enforce concurrency cap only for running operations (this tool treated as remote-backed)
    running = [o for o in ops if o.get("connection_id") == connection_id and o.get("status") == "running"]
    if len(running) >= 10:
        _log("failed", http_status=429, error_code="rate_limited", error_message="Too many concurrent operations",
             started_at=now, finished_at=now)
        return _err("RATE_LIMIT", "Too many concurrent operations")

    op_row = _log("running", started_at=now)

    # Resolve issue
    issue = None
    if issue_id is not None:
        issue = next((e for e in jira if e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("external_id") == issue_id), None)
    else:
        issue = next((e for e in jira if e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("key") == issue_key), None)
    if not issue or issue.get("status") == "deleted":
        op_row["status"] = "failed"
        op_row["http_status"] = 404
        op_row["error_code"] = "not_found"
        op_row["error_message"] = "Issue not found"
        op_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_row["updated_at"] = op_row["finished_at"]
        _save("tool_operations.json", ops)
        return _err("NOT_FOUND", "Issue not found")

    issue_ext = issue.get("external_id")

    # Filter worklogs
    worklogs = [w for w in jira if w.get("connection_id") == connection_id and w.get("entity_type") == "worklog" and w.get("issue_external_id") == issue_ext and w.get("status") == "active"]
    def _wl_started_dt(w):
        s = w.get("started_at")
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    if dt_after or dt_before:
        filtered = []
        for w in worklogs:
            dt = _wl_started_dt(w)
            if dt is None:
                continue
            if dt_after and dt < dt_after:
                continue
            if dt_before and dt > dt_before:
                continue
            filtered.append(w)
        worklogs = filtered

    # Sort by started_at ascending then id
    worklogs.sort(key=lambda w: ((_wl_started_dt(w) or datetime.datetime.min), w.get("external_id") or "", w.get("id") or ""))

    total = len(worklogs)
    page = worklogs[start_at:start_at + max_results]
    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_row["status"] = "succeeded"
    op_row["http_status"] = 200
    op_row["response_summary"] = {"total": total, "returned": len(page), "issue_external_id": issue_ext}
    op_row["affected_domain"] = "jira"
    op_row["affected_entity_type"] = "worklog"
    op_row["affected_external_ids"] = [w.get("external_id") for w in page if w.get("external_id") is not None]
    op_row["finished_at"] = finished
    op_row["updated_at"] = finished
    _save("tool_operations.json", ops)

    # Return Jira-like paging envelope
    return {
        "issue": {"id": issue_ext, "key": issue.get("key")},
        "startAt": start_at,
        "maxResults": max_results,
        "total": total,
        "worklogs": [w.get("raw") if isinstance(w.get("raw"), dict) else {"id": w.get("external_id")} for w in page],
        "meta": {"operation_id": op_row["id"], "latency_ms": int((time.time() - t0) * 1000)}
    }

def jira_download_attachments(connection_id, issue_key=None, issue_id=None, attachment_ids=None, include_inline=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "jira_download_attachments"
    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _append_op(conn_id_for_log, status, http_status=None, error_code=None, error_message=None,
                   response_summary=None, affected_external_ids=None, started_at=None, finished_at=None):
        ops = _load("tool_operations.json")
        now = _utcnow_iso()
        row = {
            "id": _gen_id("op"),
            "connection_id": conn_id_for_log if isinstance(conn_id_for_log, str) else "unknown",
            "tool_name": tool_name,
            "request": {
                "connection_id": connection_id,
                "issue_key": issue_key,
                "issue_id": issue_id,
                "attachment_ids": attachment_ids,
                "include_inline": include_inline,
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": "jira",
            "affected_entity_type": "attachment",
            "affected_external_ids": affected_external_ids,
            "started_at": started_at or now,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    def _finalize_op(op_id, **fields):
        ops = _load("tool_operations.json")
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                r.update(fields)
                r["updated_at"] = _utcnow_iso()
                _save("tool_operations.json", ops)
                return True
        return False

    def _find_active_connection(conn_id):
        conns = _load("atlassian_connections.json")
        for c in conns:
            if isinstance(c, dict) and c.get("id") == conn_id and c.get("status") == "active":
                return c
        return None

    def _rate_limit_ok(conn_id):
        ops = _load("tool_operations.json")
        now = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(seconds=60)

        remote_calls = 0
        running = 0
        for r in ops:
            if not isinstance(r, dict) or r.get("connection_id") != conn_id:
                continue
            st = r.get("status")
            if st == "running":
                running += 1
            created_at = r.get("created_at")
            if isinstance(created_at, str):
                try:
                    dt = datetime.datetime.fromisoformat(created_at.replace("Z", "+00:00"))
                except Exception:
                    dt = None
                if dt and dt.tzinfo and dt >= one_min_ago:
                    # treat tools that can touch remote as "remote Atlassian API calls"
                    remote_calls += 1
        if running >= 10:
            return False, "RATE_LIMIT", "rate_limited", "Too many concurrent operations for this connection."
        if remote_calls >= 60:
            return False, "RATE_LIMIT", "rate_limited", "Remote call rate limit exceeded for this connection."
        return True, None, None, None

    # Validate inputs
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="connection_id is malformed.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "connection_id is malformed", operation_id=op.get("id"))

    has_key = isinstance(issue_key, str) and issue_key.strip() != ""
    has_id = isinstance(issue_id, str) and issue_id.strip() != ""
    if has_key and has_id:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="Provide exactly one of issue_key or issue_id.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "Provide exactly one of issue_key or issue_id", operation_id=op.get("id"))
    if not has_key and not has_id:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="Provide exactly one of issue_key or issue_id.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "Provide exactly one of issue_key or issue_id", operation_id=op.get("id"))

    if attachment_ids is not None:
        if not isinstance(attachment_ids, list) or any((not isinstance(x, str) or not x.strip()) for x in attachment_ids):
            op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                            error_message="attachment_ids must be an array of non-empty strings.", finished_at=_utcnow_iso())
            return _err("VALIDATION_ERROR", "attachment_ids must be an array of non-empty strings", operation_id=op.get("id"))
    if include_inline is not None and not isinstance(include_inline, bool):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="include_inline must be a boolean.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "include_inline must be a boolean", operation_id=op.get("id"))

    # Auth/connection scope: must be active connection
    conn = _find_active_connection(connection_id)
    if not conn:
        op = _append_op(connection_id, "failed", http_status=401, error_code="UNAUTHORIZED",
                        error_message="All reads/writes must be scoped to a valid atlassian_connections row with status='active'.",
                        finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "All reads/writes must be scoped to a valid atlassian_connections row with status='active'.", operation_id=op.get("id"))

    ok, limit_code, norm_code, limit_msg = _rate_limit_ok(connection_id)
    if not ok:
        op = _append_op(connection_id, "failed", http_status=429, error_code=norm_code, error_message=limit_msg, finished_at=_utcnow_iso())
        return _err(limit_code, limit_msg, operation_id=op.get("id"))

    op = _append_op(connection_id, "running", started_at=_utcnow_iso())

    # Resolve issue
    jira = _load("jira_entities.json")
    issue_row = None
    if has_id:
        for r in jira:
            if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("external_id") == issue_id.strip():
                issue_row = r
                break
    else:
        for r in jira:
            if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("key") == issue_key.strip():
                issue_row = r
                break

    if not issue_row:
        _finalize_op(op["id"], status="failed", http_status=404, error_code="NOT_FOUND",
                     error_message="Issue not found in cache; remote fetch is not available in offline datastore backend.",
                     finished_at=_utcnow_iso())
        return _err("NOT_FOUND", "Issue not found", operation_id=op.get("id"))

    issue_external_id = issue_row.get("external_id")

    # Find attachments tied to issue_external_id
    attachments = []
    for r in jira:
        if not isinstance(r, dict):
            continue
        if r.get("connection_id") != connection_id or r.get("entity_type") != "attachment":
            continue
        if r.get("issue_external_id") != issue_external_id:
            continue
        if r.get("status") in ("deleted", "archived"):
            continue
        # include_inline is best-effort; no field exists, so do not filter out anything
        attachments.append(r)

    if attachment_ids is not None:
        wanted = set([x.strip() for x in attachment_ids])
        attachments = [a for a in attachments if isinstance(a.get("external_id"), str) and a.get("external_id") in wanted]

        # if user asked for ids and none exist -> NOT_FOUND (no success without effect)
        if len(wanted) > 0 and len(attachments) == 0:
            _finalize_op(op["id"], status="failed", http_status=404, error_code="NOT_FOUND",
                         error_message="No matching attachments found for the requested attachment_ids.",
                         finished_at=_utcnow_iso())
            return _err("NOT_FOUND", "No matching attachments found for the requested attachment_ids", operation_id=op.get("id"))

    # "Download" offline: return metadata
    results = []
    for a in attachments:
        results.append({
            "attachment_id": a.get("external_id"),
            "filename": a.get("attachment_filename"),
            "mime_type": a.get("attachment_mime_type"),
            "size_bytes": a.get("attachment_size_bytes"),
            "download_url": a.get("attachment_download_url"),
        })

    summary = {"issue_external_id": issue_external_id, "downloaded_count": len(results), "attachment_ids": [r.get("attachment_id") for r in results]}

    _finalize_op(op["id"], status="succeeded", http_status=200, response_summary=summary,
                 affected_external_ids=[r.get("attachment_id") for r in results], finished_at=_utcnow_iso())

    return {
        "operation_id": op.get("id"),
        "connection_id": connection_id,
        "issue": {"issue_key": issue_row.get("key"), "issue_id": issue_external_id},
        "attachments": results,
        "meta": {"count": len(results)},
    }

def jira_get_agile_boards(connection_id, name=None, project_key=None, type=None, start_at=None, max_results=None, **_extra):
    import json, os, datetime, time, re
