    op_row["affected_external_ids"] = [b.get("external_id") for b in page if b.get("external_id") is not None]
    op_row["finished_at"] = finished
    op_row["updated_at"] = finished
    _save("tool_operations.json", ops)

    is_last = (start_at + max_results) >= total
    return {
        "startAt": start_at,
        "maxResults": max_results,
        "total": total,
        "isLast": is_last,
        "values": values,
        "meta": {"operation_id": op_row["id"], "latency_ms": int((time.time() - t0) * 1000)}
