        if st and st >= cutoff:
            recent += 1
    if recent > 60:
        _finish("failed", http_status=429, error_code="rate_limited", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="rate_limited")

    rels = _load("content_relations.json")
    ents = _load("jira_entities.json")

    issue_ids = [
        r.get("to_entity_external_id")
        for r in rels
        if r.get("connection_id") == connection_id
        and r.get("domain") == "jira"
        and r.get("relation_type") == "jira_sprint_has_issue"
        and r.get("from_entity_external_id") == sprint_id
        and r.get("status") == "active"
    ]

    issues = []
    for ex_id in issue_ids:
        row = next(
            (e for e in ents
             if e.get("connection_id") == connection_id
             and e.get("entity_type") == "issue"
             and e.get("external_id") == ex_id),
            None
        )
        if row and row.get("status") != "deleted":
            issues.append(row)

    # We cannot truly execute JQL locally; record it in op.request per rule, but do not filter unless trivial.
    # Best-effort: if jql is present but not parseable, still return cached membership results.
    total = len(issues)
    page = issues[start_at:start_at + max_results]
    has_more = (start_at + max_results) < total
    next_cursor = (start_at + max_results) if has_more else None
    affected = [r.get("external_id") for r in page if r.get("external_id")]

    _finish(
        "succeeded",
        http_status=200,
        response_summary={
            "query": {"sprint_id": sprint_id, "jql": jql},
            "total": total,
            "returned": len(page),
            "start_at": start_at,
            "max_results": max_results,
        },
        affected_external_ids=affected
    )

    return {
        "issues": page,
        "start_at": start_at,
        "max_results": max_results,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "operation_id": op["id"],
        "latency_ms": int((time.time() - t0) * 1000),
    }

def jira_update_sprint(connection_id, sprint_id, name=None, state=None, start_date=None, end_date=None, complete_date=None, goal=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if not isinstance(sprint_id, str) or not sprint_id.strip():
        return _err("VALIDATION_ERROR", "Invalid sprint_id.")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "Invalid name.")
    if state is not None:
        if not isinstance(state, str) or state not in ("future", "active", "closed"):
            return _err("VALIDATION_ERROR", "Invalid state.")
    def _parse_iso(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError(field)
        # Accept ...Z or with offset; normalize store as given string if parseable.
        try:
            ss = s
            if ss.endswith("Z"):
                ss = ss[:-1]
            datetime.datetime.fromisoformat(ss)
            return s
        except Exception:
            raise ValueError(field)
    try:
        start_date_p = _parse_iso(start_date, "start_date")
        end_date_p = _parse_iso(end_date, "end_date")
        complete_date_p = _parse_iso(complete_date, "complete_date")
    except ValueError as ve:
        return _err("VALIDATION_ERROR", f"Invalid {str(ve)}; expected ISO-8601 date-time.")
    if goal is not None and not isinstance(goal, str):
        return _err("VALIDATION_ERROR", "Invalid goal.")

    # Require at least one mutable field to update
    if all(v is None for v in (name, state, start_date, end_date, complete_date, goal)):
        return _err("VALIDATION_ERROR", "No updates provided.")

    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id), None)

    ops = _load("tool_operations.json")
    def _new_op_id():
        return "op_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + os.urandom(6).hex()

    op = {
        "id": _new_op_id(),
        "connection_id": connection_id,
        "tool_name": "jira_update_sprint",
        "request": {
            "connection_id": connection_id,
            "sprint_id": sprint_id,
            "name": name,
            "state": state,
            "start_date": start_date,
            "end_date": end_date,
            "complete_date": complete_date,
            "goal": goal,
        },
        "status": "running",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "response_summary": None,
        "affected_domain": "jira",
        "affected_entity_type": "sprint",
        "affected_external_ids": None,
        "started_at": now,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)
    _save("tool_operations.json", ops)

    def _finish(status, http_status=None, error_code=None, error_message=None, response_summary=None, affected_external_ids=None):
        end = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op["status"] = status
        op["http_status"] = http_status
        op["error_code"] = error_code
        op["error_message"] = error_message
        op["response_summary"] = response_summary
        op["affected_external_ids"] = affected_external_ids
        op["finished_at"] = end
        op["updated_at"] = end
        _save("tool_operations.json", ops)

    if not conn:
        _finish("failed", http_status=404, error_code="NOT_FOUND", error_message="Connection not found.")
        return _err("NOT_FOUND", "Connection not found.")
    if conn.get("status") != "active":
        _finish("failed", http_status=401, error_code="UNAUTHORIZED", error_message="Connection is not active.")
        return _err("UNAUTHORIZED", "Connection is not active.")

    # Rate limiting / concurrency per connection_id
    running = [o for o in ops if o.get("connection_id") == connection_id and o.get("status") == "running"]
    if len(running) > 10:
        _finish("failed", http_status=429, error_code="rate_limited", error_message="Too many concurrent operations.")
        return _err("RATE_LIMIT", "Too many concurrent operations.", error_code="rate_limited")

    cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    recent = 0
    for o in ops:
        if o.get("connection_id") != connection_id:
            continue
        if o.get("tool_name") != "jira_update_sprint":
            continue
        st = _parse_dt(o.get("started_at"))
        if st and st >= cutoff:
            recent += 1
    if recent > 60:
        _finish("failed", http_status=429, error_code="rate_limited", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="rate_limited")

    ents = _load("jira_entities.json")
    sprint = next((e for e in ents
                   if e.get("connection_id") == connection_id
                   and e.get("entity_type") == "sprint"
                   and e.get("external_id") == sprint_id), None)
    if not sprint:
        _finish("failed", http_status=404, error_code="NOT_FOUND", error_message="Sprint not found.")
        return _err("NOT_FOUND", "Sprint not found.")

    if sprint.get("status") == "deleted":
        _finish("failed", http_status=409, error_code="INVALID_TRANSITION", error_message="Cannot update a deleted sprint.")
        return _err("INVALID_TRANSITION", "Cannot update a deleted sprint.")

    # Sprint state transition validation (Jira-like, simplified)
    # Allow: future->active/closed, active->closed, closed->(no transitions)
    current_state = sprint.get("sprint_state")
    if state is not None:
        allowed = {
            None: ("future", "active", "closed"),
            "future": ("active", "closed", "future"),
            "active": ("closed", "active"),
            "closed": ("closed",),
        }
        if current_state in allowed:
            if state not in allowed[current_state]:
                _finish("failed", http_status=409, error_code="CONFLICT", error_message="Requested sprint state change is not allowed.")
                return _err("CONFLICT", "Requested sprint state change is not allowed.")
        else:
            # unknown current; be conservative
            if current_state == "closed" and state != "closed":
                _finish("failed", http_status=409, error_code="CONFLICT", error_message="Requested sprint state change is not allowed.")
                return _err("CONFLICT", "Requested sprint state change is not allowed.")

    # Apply updates locally (represents post-remote-success snapshot)
    changed = False
    if name is not None and sprint.get("name") != name:
        sprint["name"] = name
        changed = True
    if state is not None and sprint.get("sprint_state") != state:
        sprint["sprint_state"] = state
        changed = True

    # Store date/goal fields in raw to preserve Jira payload
    raw = sprint.get("raw")
    if not isinstance(raw, dict):
        raw = {}
    def _set_raw(k, v):
        nonlocal raw, changed
        if v is None:
            return
        if raw.get(k) != v:
            raw[k] = v
            changed = True
    _set_raw("startDate", start_date_p)
    _set_raw("endDate", end_date_p)
    _set_raw("completeDate", complete_date_p)
    _set_raw("goal", goal)

    if not changed:
        # Idempotent no-op is allowed only if the row exists; still should record succeeded with effect=0?
        # Contract: NO SUCCESS WITHOUT EFFECT for mutations; so return NOT_FOUND-equivalent isn't right.
        # Here treat as succeeded with explicit "unchanged" would violate contract; instead require effect.
        _finish("failed", http_status=409, error_code="CONFLICT", error_message="Update had no effect.")
        return _err("CONFLICT", "Update had no effect.")

    sprint["raw"] = raw
    sprint["remote_updated_at"] = now
    sprint["updated_at"] = now

    _save("jira_entities.json", ents)

    _finish(
        "succeeded",
        http_status=200,
        response_summary={"updated": True, "sprint_id": sprint_id},
        affected_external_ids=[sprint_id]
    )

    return {
        "sprint": sprint,
        "operation_id": op["id"],
        "latency_ms": int((time.time() - t0) * 1000),
    }

def jira_create_issue(connection_id, project_key, issue_type, summary, description=None, assignee_account_id=None, reporter_account_id=None, parent_issue_key=None, epic_key=None, fields=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex.upper()}"

    def _log_op(connection_id_val, req_obj, status, http_status=None, error_code=None, error_message=None, response_summary=None, affected_domain=None, affected_entity_type=None, affected_external_ids=None, started_at=None, finished_at=None):
        ops = _load("tool_operations.json")
        op = {
            "id": _new_id("op"),
            "connection_id": connection_id_val,
            "tool_name": "jira_create_issue",
            "request": req_obj if isinstance(req_obj, dict) else {},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": affected_domain,
            "affected_entity_type": affected_entity_type,
            "affected_external_ids": affected_external_ids,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("tool_operations.json", ops)
        return op

    def _validate_str(name, v, min_len=1):
        if v is None:
            return _err("VALIDATION_ERROR", f"Missing required parameter: {name}")
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"Parameter '{name}' must be a string")
        if len(v.strip()) < min_len:
            return _err("VALIDATION_ERROR", f"Parameter '{name}' must be a non-empty string")
        return None

    # Validate inputs
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "Parameter 'connection_id' is invalid")
    e = _validate_str("project_key", project_key)
    if e: return e
    e = _validate_str("issue_type", issue_type)
    if e: return e
    e = _validate_str("summary", summary)
    if e: return e
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "Parameter 'description' must be a string when provided")
    for nm, v in [("assignee_account_id", assignee_account_id), ("reporter_account_id", reporter_account_id), ("parent_issue_key", parent_issue_key), ("epic_key", epic_key)]:
        if v is not None and not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"Parameter '{nm}' must be a string when provided")
        if isinstance(v, str) and v.strip() == "":
            return _err("VALIDATION_ERROR", f"Parameter '{nm}' must be a non-empty string when provided")
    if fields is not None and not isinstance(fields, dict):
        return _err("VALIDATION_ERROR", "Parameter 'fields' must be an object when provided")

    # Authenticate/authorize ambiently by selecting an active connection row that satisfies request prerequisites
    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id and c.get("status") == "active"), None)
    if not conn:
        _log_op(connection_id, {
            "connection_id": connection_id, "project_key": project_key, "issue_type": issue_type, "summary": summary,
            "description": description, "assignee_account_id": assignee_account_id, "reporter_account_id": reporter_account_id,
            "parent_issue_key": parent_issue_key, "epic_key": epic_key, "fields": fields
        }, status="failed", http_status=401, error_code="unauthorized", error_message="Connection is not active or does not exist", started_at=now, finished_at=now)
        return _err("UNAUTHORIZED", "Connection is not active or does not exist")

    # Rate limit: <=60 remote calls/min per connection, and <=10 concurrent running ops per connection
    ops = _load("tool_operations.json")
    running = [o for o in ops if o.get("connection_id") == connection_id and o.get("status") == "running"]
    if len(running) >= 10:
        _log_op(connection_id, {
            "connection_id": connection_id, "project_key": project_key, "issue_type": issue_type, "summary": summary,
            "description": description, "assignee_account_id": assignee_account_id, "reporter_account_id": reporter_account_id,
            "parent_issue_key": parent_issue_key, "epic_key": epic_key, "fields": fields
        }, status="failed", http_status=429, error_code="rate_limited", error_message="Too many concurrent operations", started_at=now, finished_at=now)
        return _err("RATE_LIMIT", "Too many concurrent operations")
    # remote calls/min: count succeeded+failed operations in last 60s (excluding queued/cancelled)
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    recent = 0
    for o in ops:
        if o.get("connection_id") != connection_id:
            continue
        if o.get("status") not in ("succeeded", "failed"):
            continue
        st = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
        if st and st >= cutoff:
            recent += 1
    if recent >= 60:
        _log_op(connection_id, {
            "connection_id": connection_id, "project_key": project_key, "issue_type": issue_type, "summary": summary,
            "description": description, "assignee_account_id": assignee_account_id, "reporter_account_id": reporter_account_id,
            "parent_issue_key": parent_issue_key, "epic_key": epic_key, "fields": fields
        }, status="failed", http_status=429, error_code="rate_limited", error_message="Remote rate limit exceeded", started_at=now, finished_at=now)
        return _err("RATE_LIMIT", "Remote rate limit exceeded")

    # Start operation (remote call simulated but stateful)
    op = _log_op(connection_id, {
        "connection_id": connection_id, "project_key": project_key, "issue_type": issue_type, "summary": summary,
        "description": description, "assignee_account_id": assignee_account_id, "reporter_account_id": reporter_account_id,
        "parent_issue_key": parent_issue_key, "epic_key": epic_key, "fields": fields
    }, status="running", affected_domain="jira", affected_entity_type="issue", started_at=now)

    # Validate parent/epic references if provided (must exist in cache as active/archived, not deleted)
    ents = _load("jira_entities.json")
    def _find_issue_by_key(k):
        for r in ents:
            if r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("key") == k:
                return r
        return None

    if parent_issue_key:
        pi = _find_issue_by_key(parent_issue_key)
        if pi and pi.get("status") == "deleted":
            # treat as conflict: cannot create as subtask of deleted issue
            # finish op
            ops2 = _load("tool_operations.json")
            for row in ops2:
                if row.get("id") == op["id"]:
                    row["status"] = "failed"
                    row["http_status"] = 409
                    row["error_code"] = "conflict"
                    row["error_message"] = "Parent issue is deleted"
                    row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    row["updated_at"] = row["finished_at"]
                    break
            _save("tool_operations.json", ops2)
            return _err("CONFLICT", "Parent issue is deleted")
    if epic_key:
        ei = _find_issue_by_key(epic_key)
        if ei and ei.get("status") == "deleted":
            ops2 = _load("tool_operations.json")
            for row in ops2:
                if row.get("id") == op["id"]:
                    row["status"] = "failed"
                    row["http_status"] = 409
                    row["error_code"] = "conflict"
                    row["error_message"] = "Epic issue is deleted"
                    row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    row["updated_at"] = row["finished_at"]
                    break
            _save("tool_operations.json", ops2)
            return _err("CONFLICT", "Epic issue is deleted")

    # "Remote success": generate external_id and issue key, then upsert jira_entities(issue)
    # Determine next key number per project_key by scanning existing keys ABC-<n>
    max_n = 0
    key_re = re.compile(rf"^{re.escape(project_key)}-(\d+)$")
    for r in ents:
        if r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and isinstance(r.get("key"), str):
            m = key_re.match(r["key"])
            if m:
                try:
                    max_n = max(max_n, int(m.group(1)))
                except Exception:
                    pass
    new_key = f"{project_key}-{max_n + 1}"
    new_external_id = f"JIRA_ISSUE_{uuid.uuid4().hex}"

    # Uniqueness check: (connection_id, entity_type, external_id)
    if any(r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("external_id") == new_external_id for r in ents):
        # extremely unlikely, retry once
        new_external_id = f"JIRA_ISSUE_{uuid.uuid4().hex}"
        if any(r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("external_id") == new_external_id for r in ents):
            ops2 = _load("tool_operations.json")
            for row in ops2:
                if row.get("id") == op["id"]:
                    row["status"] = "failed"
                    row["http_status"] = 409
                    row["error_code"] = "conflict"
                    row["error_message"] = "Duplicate external_id generated"
                    row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    row["updated_at"] = row["finished_at"]
                    break
            _save("tool_operations.json", ops2)
            return _err("CONFLICT", "Could not allocate unique issue id")

    # Create entity row
    created_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    issue_row = {
        "id": _new_id("jira_ent"),
        "connection_id": connection_id,
        "entity_type": "issue",
        "external_id": new_external_id,
        "key": new_key,
        "name": None,
        "parent_external_id": None,
        "project_external_id": project_key,  # stored as external-ish ref per constraints requires not null
        "issue_external_id": None,
        "from_issue_external_id": None,
        "to_issue_external_id": None,
        "link_type": None,
        "status_category": "To Do",
        "status_name": "To Do",
        "sprint_state": None,
        "board_type": None,
        "assignee_account_id": assignee_account_id,
        "reporter_account_id": reporter_account_id,
        "summary": summary,
        "description_text": description,
        "body_text": None,
        "time_spent_seconds": None,
        "started_at": None,
        "attachment_filename": None,
        "attachment_mime_type": None,
        "attachment_size_bytes": None,
        "attachment_download_url": None,
        "remote_updated_at": created_at,
        "status": "active",
        "raw": {
            "id": new_external_id,
            "key": new_key,
            "fields": {
                "project": {"key": project_key},
                "issuetype": {"name": issue_type},
                "summary": summary,
                "description": description,
                "assignee": {"accountId": assignee_account_id} if assignee_account_id else None,
                "reporter": {"accountId": reporter_account_id} if reporter_account_id else None,
                "parent": {"key": parent_issue_key} if parent_issue_key else None,
                "epic": {"key": epic_key} if epic_key else None,
            },
            "custom_fields": fields if isinstance(fields, dict) else {},
        },
        "created_at": created_at,
        "updated_at": created_at,
    }

    # Ensure required fields per constraint: issue implies key not null and project_external_id not null
    if not issue_row.get("key") or not issue_row.get("project_external_id"):
        ops2 = _load("tool_operations.json")
        for row in ops2:
            if row.get("id") == op["id"]:
                row["status"] = "failed"
                row["http_status"] = 400
                row["error_code"] = "validation_error"
                row["error_message"] = "Issue key/project missing"
                row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                row["updated_at"] = row["finished_at"]
                break
        _save("tool_operations.json", ops2)
        return _err("VALIDATION_ERROR", "Issue key/project missing")

    ents.append(issue_row)
    _save("jira_entities.json", ents)

    # Create/refresh relations for epic/parent when provided
    rels = _load("content_relations.json")
    def _upsert_edge(rel_type, from_issue_ext, to_issue_ext, from_type="issue", to_type="issue"):
        # Unique(connection_id, domain, relation_type, from_entity_external_id, to_entity_external_id)
        existing = None
        for r in rels:
            if r.get("connection_id") == connection_id and r.get("domain") == "jira" and r.get("relation_type") == rel_type and r.get("from_entity_external_id") == from_issue_ext and r.get("to_entity_external_id") == to_issue_ext:
                existing = r
                break
        if existing:
            # transition removed->active allowed
            existing["status"] = "active"
            existing["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            return existing["id"]
        edge = {
            "id": _new_id("rel"),
            "connection_id": connection_id,
            "domain": "jira",
            "relation_type": rel_type,
            "from_entity_external_id": from_issue_ext,
            "to_entity_external_id": to_issue_ext,
            "from_entity_type": from_type,
            "to_entity_type": to_type,
            "status": "active",
            "raw": None,
            "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        }
        rels.append(edge)
        return edge["id"]

    if parent_issue_key:
        pi = _find_issue_by_key(parent_issue_key)
        if pi:
            issue_row["parent_external_id"] = pi.get("external_id")
            issue_row["raw"]["fields"]["parent"] = {"id": pi.get("external_id"), "key": parent_issue_key}
            issue_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            # for jira_parent_of, convention: parent -> child
            _upsert_edge("jira_parent_of", pi.get("external_id"), new_external_id)
            _save("jira_entities.json", ents)
    if epic_key:
        ei = _find_issue_by_key(epic_key)
        if ei:
            issue_row["raw"]["fields"]["epic"] = {"id": ei.get("external_id"), "key": epic_key}
            issue_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            # for jira_epic_of, convention: epic -> child
            _upsert_edge("jira_epic_of", ei.get("external_id"), new_external_id)
            _save("jira_entities.json", ents)

    _save("content_relations.json", rels)

    # Finish operation as succeeded
    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    ops2 = _load("tool_operations.json")
    for row in ops2:
        if row.get("id") == op["id"]:
            row["status"] = "succeeded"
            row["http_status"] = 201
            row["response_summary"] = {"created": 1, "issue_external_id": new_external_id, "issue_key": new_key}
            row["affected_external_ids"] = [new_external_id]
            row["finished_at"] = finished
            row["updated_at"] = finished
            break
    _save("tool_operations.json", ops2)

    return {"issue": issue_row, "operation_id": op["id"], "latency_ms": int((time.time() - t0) * 1000)}

def jira_batch_create_issues(connection_id, issues, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
