            "connection_id": connection_id_val,
            "tool_name": "jira_batch_create_issues",
            "request": req_obj if isinstance(req_obj, dict) else {},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": affected_domain,
            "affected_entity_type": affected_entity_type,
            "affected_external_ids": affected_external_ids,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("tool_operations.json", ops)
        return op

    # Validate inputs
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "Parameter 'connection_id' is invalid")
    if not isinstance(issues, list) or len(issues) < 1:
        return _err("VALIDATION_ERROR", "Parameter 'issues' must be a non-empty array")
    for i, it in enumerate(issues):
        if not isinstance(it, dict):
            return _err("VALIDATION_ERROR", f"issues[{i}] must be an object")
        for req in ("project_key", "issue_type", "summary"):
            if req not in it:
                return _err("VALIDATION_ERROR", f"issues[{i}] is missing required field '{req}'")
            if not isinstance(it.get(req), str) or it.get(req, "").strip() == "":
                return _err("VALIDATION_ERROR", f"issues[{i}].{req} must be a non-empty string")
        if "description" in it and it["description"] is not None and not isinstance(it["description"], str):
            return _err("VALIDATION_ERROR", f"issues[{i}].description must be a string when provided")
        for nm in ("assignee_account_id", "reporter_account_id", "parent_issue_key", "epic_key"):
            if nm in it and it[nm] is not None and not isinstance(it[nm], str):
                return _err("VALIDATION_ERROR", f"issues[{i}].{nm} must be a string when provided")
        if "fields" in it and it["fields"] is not None and not isinstance(it["fields"], dict):
            return _err("VALIDATION_ERROR", f"issues[{i}].fields must be an object when provided")

    # Connection must be active
    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id and c.get("status") == "active"), None)
    if not conn:
        _log_op(connection_id, {"connection_id": connection_id, "issues": issues}, status="failed", http_status=401, error_code="unauthorized", error_message="Connection is not active or does not exist", started_at=now, finished_at=now)
        return _err("UNAUTHORIZED", "Connection is not active or does not exist")

    # Rate limit/concurrency
    ops = _load("tool_operations.json")
    running = [o for o in ops if o.get("connection_id") == connection_id and o.get("status") == "running"]
    if len(running) >= 10:
        _log_op(connection_id, {"connection_id": connection_id, "issues": issues}, status="failed", http_status=429, error_code="rate_limited", error_message="Too many concurrent operations", started_at=now, finished_at=now)
        return _err("RATE_LIMIT", "Too many concurrent operations")
    cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
    recent = 0
    for o in ops:
        if o.get("connection_id") != connection_id: continue
        if o.get("status") not in ("succeeded", "failed"): continue
        st = _parse_dt(o.get("started_at")) or _parse_dt(o.get("created_at"))
        if st and st >= cutoff:
            recent += 1
    # Batch create is a single remote call in this backend
    if recent >= 60:
        _log_op(connection_id, {"connection_id": connection_id, "issues": issues}, status="failed", http_status=429, error_code="rate_limited", error_message="Remote rate limit exceeded", started_at=now, finished_at=now)
        return _err("RATE_LIMIT", "Remote rate limit exceeded")

    op = _log_op(connection_id, {"connection_id": connection_id, "issues": issues}, status="running", affected_domain="jira", affected_entity_type="issue", started_at=now)

    ents = _load("jira_entities.json")

    def _find_issue_by_key(k):
        for r in ents:
            if r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("key") == k:
                return r
        return None

    # Precompute per-project next key numbers
    proj_max = {}
    for r in ents:
        if r.get("connection_id") != connection_id or r.get("entity_type") != "issue":
            continue
        k = r.get("key")
        if not isinstance(k, str) or "-" not in k:
            continue
        pk, num = k.split("-", 1)
        try:
            n = int(num)
        except Exception:
            continue
        proj_max[pk] = max(proj_max.get(pk, 0), n)

    created_rows = []
    results = []
    affected = []

    # Simulate remote per-item result; only persist successful items (business rule)
    for i, it in enumerate(issues):
        pk = it["project_key"]
        proj_max[pk] = proj_max.get(pk, 0) + 1
        new_key = f"{pk}-{proj_max[pk]}"
        new_external_id = f"JIRA_ISSUE_{uuid.uuid4().hex}"
        # Ensure no collision on (connection_id, entity_type, external_id)
        if any(r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("external_id") == new_external_id for r in ents):
            results.append({"index": i, "error": {"code": "conflict", "message": "Duplicate external_id generated"}})
            continue

        created_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": _new_id("jira_ent"),
            "connection_id": connection_id,
            "entity_type": "issue",
            "external_id": new_external_id,
            "key": new_key,
            "name": None,
            "parent_external_id": None,
            "project_external_id": pk,
            "issue_external_id": None,
            "from_issue_external_id": None,
            "to_issue_external_id": None,
            "link_type": None,
            "status_category": "To Do",
            "status_name": "To Do",
            "sprint_state": None,
            "board_type": None,
            "assignee_account_id": it.get("assignee_account_id"),
            "reporter_account_id": it.get("reporter_account_id"),
            "summary": it.get("summary"),
            "description_text": it.get("description"),
            "body_text": None,
            "time_spent_seconds": None,
            "started_at": None,
            "attachment_filename": None,
            "attachment_mime_type": None,
            "attachment_size_bytes": None,
            "attachment_download_url": None,
            "remote_updated_at": created_at,
            "status": "active",
            "raw": {
                "id": new_external_id,
                "key": new_key,
                "fields": {
                    "project": {"key": pk},
                    "issuetype": {"name": it.get("issue_type")},
                    "summary": it.get("summary"),
                    "description": it.get("description"),
                    "assignee": {"accountId": it.get("assignee_account_id")} if it.get("assignee_account_id") else None,
                    "reporter": {"accountId": it.get("reporter_account_id")} if it.get("reporter_account_id") else None,
                    "parent": {"key": it.get("parent_issue_key")} if it.get("parent_issue_key") else None,
                    "epic": {"key": it.get("epic_key")} if it.get("epic_key") else None,
                },
                "custom_fields": it.get("fields") if isinstance(it.get("fields"), dict) else {},
            },
            "created_at": created_at,
            "updated_at": created_at,
        }

        # Validate parent/epic if present and cached as deleted
        if it.get("parent_issue_key"):
            pi = _find_issue_by_key(it["parent_issue_key"])
            if pi and pi.get("status") == "deleted":
                results.append({"index": i, "error": {"code": "conflict", "message": "Parent issue is deleted"}})
                continue
            if pi:
                row["parent_external_id"] = pi.get("external_id")
                row["raw"]["fields"]["parent"] = {"id": pi.get("external_id"), "key": it["parent_issue_key"]}
        if it.get("epic_key"):
            ei = _find_issue_by_key(it["epic_key"])
            if ei and ei.get("status") == "deleted":
                results.append({"index": i, "error": {"code": "conflict", "message": "Epic issue is deleted"}})
                continue
            if ei:
                row["raw"]["fields"]["epic"] = {"id": ei.get("external_id"), "key": it["epic_key"]}

        created_rows.append(row)
        results.append({"index": i, "issue": {"external_id": new_external_id, "key": new_key}})
        affected.append(new_external_id)

    if created_rows:
        ents.extend(created_rows)
        _save("jira_entities.json", ents)

    # Relations: add for items whose epic/parent resolved to cached issues (best-effort, only for supported semantic relations)
    rels = _load("content_relations.json")
    def _upsert_edge(rel_type, from_ext, to_ext):
        existing = None
        for r in rels:
            if r.get("connection_id") == connection_id and r.get("domain") == "jira" and r.get("relation_type") == rel_type and r.get("from_entity_external_id") == from_ext and r.get("to_entity_external_id") == to_ext:
                existing = r
                break
        if existing:
            existing["status"] = "active"
            existing["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            return
        rels.append({
            "id": _new_id("rel"),
            "connection_id": connection_id,
            "domain": "jira",
            "relation_type": rel_type,
            "from_entity_external_id": from_ext,
            "to_entity_external_id": to_ext,
            "from_entity_type": "issue",
            "to_entity_type": "issue",
            "status": "active",
            "raw": None,
            "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        })

    # Build map from key to external_id for cached issues + newly created issues
    key_to_ext = {}
    for r in ents:
        if r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and isinstance(r.get("key"), str) and isinstance(r.get("external_id"), str):
            key_to_ext[r["key"]] = r["external_id"]

    for row in created_rows:
        parent_key = None
        epic_key = None
        try:
            parent_key = (row.get("raw") or {}).get("fields", {}).get("parent", {}).get("key")
        except Exception:
            parent_key = None
        try:
            epic_key = (row.get("raw") or {}).get("fields", {}).get("epic", {}).get("key")
        except Exception:
            epic_key = None
        if parent_key and parent_key in key_to_ext:
            _upsert_edge("jira_parent_of", key_to_ext[parent_key], row["external_id"])
        if epic_key and epic_key in key_to_ext:
            _upsert_edge("jira_epic_of", key_to_ext[epic_key], row["external_id"])

    _save("content_relations.json", rels)

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    ops2 = _load("tool_operations.json")
    for row in ops2:
        if row.get("id") == op["id"]:
            row["status"] = "succeeded"
            row["http_status"] = 201
            row["response_summary"] = {"requested": len(issues), "created": len(created_rows), "failed": len(issues) - len(created_rows)}
            row["affected_external_ids"] = affected
            row["finished_at"] = finished
            row["updated_at"] = finished
            break
    _save("tool_operations.json", ops2)

    return {"results": results, "created_external_ids": affected, "operation_id": op["id"], "latency_ms": int((time.time() - t0) * 1000)}

