                    row["updated_at"] = finished
                    break
            _save("tool_operations.json", ops2)
            return _err("VALIDATION_ERROR", "transition_id is not valid for this issue (no cached transitions match)")

    # Apply updates
    updated = False
    if summary is not None:
        issue["summary"] = summary
        issue.setdefault("raw", {}).setdefault("fields", {})["summary"] = summary
        updated = True
    if description is not None:
        issue["description_text"] = description
        issue.setdefault("raw", {}).setdefault("fields", {})["description"] = description
        updated = True
    if assignee_account_id is not None:
        issue["assignee_account_id"] = assignee_account_id
        issue.setdefault("raw", {}).setdefault("fields", {})["assignee"] = {"accountId": assignee_account_id}
        updated = True
    if reporter_account_id is not None:
        issue["reporter_account_id"] = reporter_account_id
        issue.setdefault("raw", {}).setdefault("fields", {})["reporter"] = {"accountId": reporter_account_id}
        updated = True
    if isinstance(fields, dict):
        issue.setdefault("raw", {}).setdefault("custom_fields", {}).update(fields)
        updated = True

    # Relationship changes (epic/parent): reflect in content_relations, mark previous removed
    rels = _load("content_relations.json")

    def _find_issue_by_key(k):
        for r in ents:
            if r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("key") == k:
                return r
        return None

    issue_ext = issue.get("external_id")
    if not issue_ext:
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        ops2 = _load("tool_operations.json")
        for row in ops2:
            if row.get("id") == op["id"]:
                row["status"] = "failed"
                row["http_status"] = 500
                row["error_code"] = "failed"
                row["error_message"] = "Cached issue missing external_id"
                row["finished_at"] = finished
                row["updated_at"] = finished
                break
        _save("tool_operations.json", ops2)
        return _err("CONFLICT", "Cached issue missing external_id")

    def _mark_removed(rel_type, predicate):
        changed = 0
        for r in rels:
            if r.get("connection_id") != connection_id or r.get("domain") != "jira" or r.get("relation_type") != rel_type:
                continue
            if r.get("status") != "active":
                continue
            if predicate(r):
                r["status"] = "removed"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                changed += 1
        return changed

    def _upsert_edge(rel_type, from_ext, to_ext):
        existing = None
        for r in rels:
            if r.get("connection_id") == connection_id and r.get("domain") == "jira" and r.get("relation_type") == rel_type and r.get("from_entity_external_id") == from_ext and r.get("to_entity_external_id") == to_ext:
                existing = r
                break
        if existing:
            existing["status"] = "active"
            existing["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            return existing["id"]
        rels.append({
            "id": _new_id("rel"),
            "connection_id": connection_id,
            "domain": "jira",
            "relation_type": rel_type,
            "from_entity_external_id": from_ext,
            "to_entity_external_id": to_ext,
            "from_entity_type": "issue",
            "to_entity_type": "issue",
            "status": "active",
            "raw": None,
            "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        })
        return rels[-1]["id"]

    if parent_issue_key is not None:
        # remove any existing parent_of edges pointing to this issue as child
        _mark_removed("jira_parent_of", lambda r: r.get("to_entity_external_id") == issue_ext)
        if parent_issue_key:
            pi = _find_issue_by_key(parent_issue_key)
            if pi and pi.get("status") == "deleted":
                finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                ops2 = _load("tool_operations.json")
                for row in ops2:
                    if row.get("id") == op["id"]:
                        row["status"] = "failed"
                        row["http_status"] = 409
                        row["error_code"] = "conflict"
                        row["error_message"] = "Parent issue is deleted"
                        row["finished_at"] = finished
                        row["updated_at"] = finished
                        break
                _save("tool_operations.json", ops2)
                return _err("CONFLICT", "Parent issue is deleted")
            if pi:
                issue["parent_external_id"] = pi.get("external_id")
                issue.setdefault("raw", {}).setdefault("fields", {})["parent"] = {"id": pi.get("external_id"), "key": parent_issue_key}
                _upsert_edge("jira_parent_of", pi.get("external_id"), issue_ext)
        else:
            issue["parent_external_id"] = None
            issue.setdefault("raw", {}).setdefault("fields", {})["parent"] = None
        updated = True

    if epic_key is not None:
        _mark_removed("jira_epic_of", lambda r: r.get("to_entity_external_id") == issue_ext)
        if epic_key:
            ei = _find_issue_by_key(epic_key)
            if ei and ei.get("status") == "deleted":
                finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                ops2 = _load("tool_operations.json")
                for row in ops2:
                    if row.get("id") == op["id"]:
                        row["status"] = "failed"
                        row["http_status"] = 409
                        row["error_code"] = "conflict"
                        row["error_message"] = "Epic issue is deleted"
                        row["finished_at"] = finished
                        row["updated_at"] = finished
                        break
                _save("tool_operations.json", ops2)
                return _err("CONFLICT", "Epic issue is deleted")
            if ei:
                issue.setdefault("raw", {}).setdefault("fields", {})["epic"] = {"id": ei.get("external_id"), "key": epic_key}
                _upsert_edge("jira_epic_of", ei.get("external_id"), issue_ext)
        else:
            issue.setdefault("raw", {}).setdefault("fields", {})["epic"] = None
        updated = True

    # Apply transition effect if requested: set status_name/category (simulate)
    if transition_id:
        # best-effort derive destination from transitions list
        raw = issue.get("raw") if isinstance(issue.get("raw"), dict) else {}
        transitions = raw.get("transitions")
        dest_name = None
        dest_cat = None
        if isinstance(transitions, list):
            for tr in transitions:
                if not isinstance(tr, dict):
                    continue
                if str(tr.get("id")) == transition_id or str(tr.get("name")) == transition_id:
                    dest = tr.get("to") if isinstance(tr.get("to"), dict) else {}
                    dest_name = dest.get("name") or tr.get("to_status_name") or tr.get("name")
                    dest_cat = (dest.get("statusCategory") or {}).get("name") if isinstance(dest.get("statusCategory"), dict) else tr.get("to_status_category")
                    break
        issue["status_name"] = dest_name or issue.get("status_name") or "In Progress"
        issue["status_category"] = dest_cat or issue.get("status_category") or "In Progress"
        issue.setdefault("raw", {})["last_transition"] = {"requested": transition_id, "applied_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"}
        updated = True

    if not updated:
        # No-op update is not allowed to report success without effect
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        ops2 = _load("tool_operations.json")
        for row in ops2:
            if row.get("id") == op["id"]:
                row["status"] = "failed"
                row["http_status"] = 400
                row["error_code"] = "validation_error"
                row["error_message"] = "No update fields provided"
                row["finished_at"] = finished
                row["updated_at"] = finished
                break
        _save("tool_operations.json", ops2)
        return _err("VALIDATION_ERROR", "No update fields provided")

    issue["remote_updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    issue["updated_at"] = issue["remote_updated_at"]

    _save("jira_entities.json", ents)
    _save("content_relations.json", rels)

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    ops2 = _load("tool_operations.json")
    for row in ops2:
        if row.get("id") == op["id"]:
            row["status"] = "succeeded"
            row["http_status"] = 200
            row["response_summary"] = {"updated": 1, "issue_external_id": issue_ext, "issue_key": issue_key}
            row["affected_external_ids"] = [issue_ext]
            row["finished_at"] = finished
            row["updated_at"] = finished
            break
    _save("tool_operations.json", ops2)

    return {"issue": issue, "operation_id": op["id"], "latency_ms": int((time.time() - t0) * 1000)}

def jira_delete_issue(connection_id, issue_key, delete_subtasks=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "jira_delete_issue"
    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _append_op(conn_id_for_log, status, http_status=None, error_code=None, error_message=None,
                   response_summary=None, affected_external_ids=None, started_at=None, finished_at=None):
        ops = _load("tool_operations.json")
        now = _utcnow_iso()
        row = {
            "id": _gen_id("op"),
            "connection_id": conn_id_for_log if isinstance(conn_id_for_log, str) else "unknown",
            "tool_name": tool_name,
            "request": {"connection_id": connection_id, "issue_key": issue_key, "delete_subtasks": delete_subtasks},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": "jira",
            "affected_entity_type": "issue",
            "affected_external_ids": affected_external_ids,
            "started_at": started_at or now,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    def _finalize_op(op_id, **fields):
        ops = _load("tool_operations.json")
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                r.update(fields)
                r["updated_at"] = _utcnow_iso()
                _save("tool_operations.json", ops)
                return True
        return False

    def _find_active_connection(conn_id):
        for c in _load("atlassian_connections.json"):
            if isinstance(c, dict) and c.get("id") == conn_id and c.get("status") == "active":
                return c
        return None

    def _rate_limit_ok(conn_id):
        ops = _load("tool_operations.json")
        now = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(seconds=60)
        remote_calls = 0
        running = 0
        for r in ops:
            if not isinstance(r, dict) or r.get("connection_id") != conn_id:
                continue
            if r.get("status") == "running":
                running += 1
            created_at = r.get("created_at")
            if isinstance(created_at, str):
                try:
                    dt = datetime.datetime.fromisoformat(created_at.replace("Z", "+00:00"))
                except Exception:
                    dt = None
                if dt and dt.tzinfo and dt >= one_min_ago:
                    remote_calls += 1
        if running >= 10:
            return False, "RATE_LIMIT", "rate_limited", "Too many concurrent operations for this connection."
        if remote_calls >= 60:
            return False, "RATE_LIMIT", "rate_limited", "Remote call rate limit exceeded for this connection."
        return True, None, None, None

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="connection_id is malformed.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "connection_id is malformed", operation_id=op.get("id"))

    if not isinstance(issue_key, str) or not issue_key.strip():
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="issue_key is required.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "issue_key is required", operation_id=op.get("id"))

    if delete_subtasks is not None and not isinstance(delete_subtasks, bool):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="delete_subtasks must be a boolean when provided.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "delete_subtasks must be a boolean when provided", operation_id=op.get("id"))

    conn = _find_active_connection(connection_id)
    if not conn:
        op = _append_op(connection_id, "failed", http_status=401, error_code="UNAUTHORIZED",
                        error_message="All reads/writes must be scoped to a valid atlassian_connections row with status='active'.",
                        finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "All reads/writes must be scoped to a valid atlassian_connections row with status='active'.", operation_id=op.get("id"))

    ok, limit_code, norm_code, limit_msg = _rate_limit_ok(connection_id)
    if not ok:
        op = _append_op(connection_id, "failed", http_status=429, error_code=norm_code, error_message=limit_msg, finished_at=_utcnow_iso())
        return _err(limit_code, limit_msg, operation_id=op.get("id"))

    op = _append_op(connection_id, "running", started_at=_utcnow_iso())

    jira = _load("jira_entities.json")
    issue = None
    for r in jira:
        if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("key") == issue_key.strip():
            issue = r
            break

    if not issue:
        _finalize_op(op["id"], status="failed", http_status=404, error_code="NOT_FOUND",
                     error_message="Issue not found in cache; remote delete is not available in offline datastore backend.",
                     finished_at=_utcnow_iso())
        return _err("NOT_FOUND", "Issue not found", operation_id=op.get("id"))

    # Idempotent: if already deleted, succeed with no additional changes
    now = _utcnow_iso()
    affected = []
    issue_external_id = issue.get("external_id")

    if issue.get("status") != "deleted":
        # Transition active/archived -> deleted allowed; deleted -> none
        issue["status"] = "deleted"
        issue["updated_at"] = now
        affected.append(issue_external_id)

        # Cascade: related entities archived (not deleted)
        for r in jira:
            if not isinstance(r, dict):
                continue
            if r.get("connection_id") != connection_id:
                continue
            if r.get("entity_type") in ("comment", "worklog", "attachment", "issue_link"):
                if r.get("issue_external_id") == issue_external_id:
                    if r.get("status") == "active":
                        r["status"] = "archived"
                        r["updated_at"] = now
            # also archive issue_link where from/to references match
            if r.get("entity_type") == "issue_link":
                if r.get("from_issue_external_id") == issue_external_id or r.get("to_issue_external_id") == issue_external_id:
                    if r.get("status") == "active":
                        r["status"] = "archived"
                        r["updated_at"] = now

        _save("jira_entities.json", jira)

    # Also remove any content_relations edges for this issue (best-effort, not specified but aligns with "removed" edges usage)
    rels = _load("content_relations.json")
    changed_rel = False
    for e in rels:
        if not isinstance(e, dict) or e.get("connection_id") != connection_id or e.get("domain") != "jira":
            continue
        if e.get("from_entity_external_id") == issue_external_id or e.get("to_entity_external_id") == issue_external_id:
            if e.get("status") == "active":
                e["status"] = "removed"
                e["updated_at"] = now
                changed_rel = True
    if changed_rel:
        _save("content_relations.json", rels)

    _finalize_op(op["id"], status="succeeded", http_status=204,
                 response_summary={"deleted": True, "issue_key": issue_key.strip(), "issue_external_id": issue_external_id, "delete_subtasks": bool(delete_subtasks)},
                 affected_external_ids=affected, finished_at=_utcnow_iso())

    return {
        "operation_id": op.get("id"),
        "connection_id": connection_id,
        "deleted": True,
        "issue": {"key": issue_key.strip(), "id": issue_external_id},
        "delete_subtasks": bool(delete_subtasks),
    }

