    if issue.get("status") == "deleted":
        _finalize_op(op["id"], status="failed", http_status=409, error_code="CONFLICT",
                     error_message="Cannot add comment to an issue that is deleted in the cache.", finished_at=_utcnow_iso())
        return _err("CONFLICT", "Cannot add comment to an issue that is deleted in the cache", operation_id=op.get("id"))

    # Create comment row (idempotency: no request id available; so always create new)
    now = _utcnow_iso()
    new_comment_external_id = str(int(time.time() * 1000))  # stable-ish numeric string
    new_row = {
        "id": _gen_id("jira_ent"),
        "connection_id": connection_id,
        "entity_type": "comment",
        "external_id": new_comment_external_id,
        "key": None,
        "name": None,
        "parent_external_id": None,
        "project_external_id": issue.get("project_external_id"),
        "issue_external_id": issue.get("external_id"),
        "from_issue_external_id": None,
        "to_issue_external_id": None,
        "link_type": None,
        "status_category": None,
        "status_name": None,
        "sprint_state": None,
        "board_type": None,
        "assignee_account_id": None,
        "reporter_account_id": None,
        "summary": None,
        "description_text": None,
        "body_text": body.strip(),
        "time_spent_seconds": None,
        "started_at": None,
        "attachment_filename": None,
        "attachment_mime_type": None,
        "attachment_size_bytes": None,
        "attachment_download_url": None,
        "remote_updated_at": now,
        "status": "active",
        "raw": {
            "id": new_comment_external_id,
            "body": body.strip(),
            "issueId": issue.get("external_id"),
            "issueKey": issue.get("key"),
            "created": now,
        },
        "created_at": now,
        "updated_at": now,
    }
    jira.append(new_row)

    # Upsert issue snapshot to reflect new comment count if raw present
    if isinstance(issue.get("raw"), dict):
        raw = issue["raw"]
        fields = raw.get("fields")
        if isinstance(fields, dict):
            comment = fields.get("comment")
            if isinstance(comment, dict):
                total = comment.get("total")
                if isinstance(total, int):
                    comment["total"] = total + 1
                elif total is None:
                    comment["total"] = 1
                fields["comment"] = comment
            else:
                fields["comment"] = {"total": 1}
            raw["fields"] = fields
            issue["raw"] = raw
        issue["updated_at"] = now

    _save("jira_entities.json", jira)

    _finalize_op(op["id"], status="succeeded", http_status=201,
                 response_summary={"created_comment_id": new_comment_external_id, "issue_external_id": issue.get("external_id")},
                 affected_external_ids=[new_comment_external_id], finished_at=_utcnow_iso())

    return {
        "operation_id": op.get("id"),
        "connection_id": connection_id,
        "issue": {"key": issue.get("key"), "id": issue.get("external_id")},
        "comment": {
            "id": new_comment_external_id,
            "body": body.strip(),
            "created": now,
        },
    }

def jira_add_worklog(connection_id, time_spent_seconds, issue_key=None, issue_id=None, comment=None, started_at=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "jira_add_worklog"
    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _parse_iso_dt(s):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, "started_at must be an ISO-8601 datetime string when provided."
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss.replace("Z", "+00:00"))
            else:
                m = re.match(r"^(.*)([+-]\d{2})(\d{2})$", ss)
                if m:
                    ss = m.group(1) + m.group(2) + ":" + m.group(3)
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                return None, "started_at must include a timezone (e.g., 'Z' or '+00:00')."
            dt = dt.astimezone(datetime.timezone.utc)
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z"), None
        except Exception:
            return None, "started_at must be an ISO-8601 datetime string when provided."

    def _append_op(conn_id_for_log, status, http_status=None, error_code=None, error_message=None,
                   response_summary=None, affected_external_ids=None, started_at_iso=None, finished_at=None):
        ops = _load("tool_operations.json")
        now = _utcnow_iso()
        row = {
            "id": _gen_id("op"),
            "connection_id": conn_id_for_log if isinstance(conn_id_for_log, str) else "unknown",
            "tool_name": tool_name,
            "request": {
                "connection_id": connection_id,
                "issue_key": issue_key,
                "issue_id": issue_id,
                "comment": comment,
                "time_spent_seconds": time_spent_seconds,
                "started_at": started_at,
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": "jira",
            "affected_entity_type": "worklog",
            "affected_external_ids": affected_external_ids,
            "started_at": started_at_iso or now,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    def _finalize_op(op_id, **fields):
        ops = _load("tool_operations.json")
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                r.update(fields)
                r["updated_at"] = _utcnow_iso()
                _save("tool_operations.json", ops)
                return True
        return False

    def _find_active_connection(conn_id):
        for c in _load("atlassian_connections.json"):
            if isinstance(c, dict) and c.get("id") == conn_id and c.get("status") == "active":
                return c
        return None

    def _rate_limit_ok(conn_id):
        ops = _load("tool_operations.json")
        now = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(seconds=60)
        remote_calls = 0
        running = 0
        for r in ops:
            if not isinstance(r, dict) or r.get("connection_id") != conn_id:
                continue
            if r.get("status") == "running":
                running += 1
            created_at = r.get("created_at")
            if isinstance(created_at, str):
                try:
                    dt = datetime.datetime.fromisoformat(created_at.replace("Z", "+00:00"))
                except Exception:
                    dt = None
                if dt and dt.tzinfo and dt >= one_min_ago:
                    remote_calls += 1
        if running >= 10:
            return False, "RATE_LIMIT", "rate_limited", "Too many concurrent operations for this connection."
        if remote_calls >= 60:
            return False, "RATE_LIMIT", "rate_limited", "Remote call rate limit exceeded for this connection."
        return True, None, None, None

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="connection_id is malformed.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "connection_id is malformed", operation_id=op.get("id"))

    if not isinstance(time_spent_seconds, int) or time_spent_seconds < 1:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="time_spent_seconds must be an integer >= 1.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "time_spent_seconds must be an integer >= 1", operation_id=op.get("id"))

    has_key = isinstance(issue_key, str) and issue_key.strip() != ""
    has_id = isinstance(issue_id, str) and issue_id.strip() != ""
    if has_key and has_id:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="Provide exactly one of issue_key or issue_id.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "Provide exactly one of issue_key or issue_id", operation_id=op.get("id"))
    if not has_key and not has_id:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="Provide issue_key or issue_id.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "Provide issue_key or issue_id", operation_id=op.get("id"))

    started_at_iso, started_err = _parse_iso_dt(started_at)
    if started_err:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message=started_err, finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", started_err, operation_id=op.get("id"))

    conn = _find_active_connection(connection_id)
    if not conn:
        op = _append_op(connection_id, "failed", http_status=401, error_code="UNAUTHORIZED",
                        error_message="All reads/writes must be scoped to a valid atlassian_connections row with status='active'.",
                        finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "All reads/writes must be scoped to a valid atlassian_connections row with status='active'.", operation_id=op.get("id"))

    ok, limit_code, norm_code, limit_msg = _rate_limit_ok(connection_id)
    if not ok:
        op = _append_op(connection_id, "failed", http_status=429, error_code=norm_code, error_message=limit_msg, finished_at=_utcnow_iso())
        return _err(limit_code, limit_msg, operation_id=op.get("id"))

    op = _append_op(connection_id, "running", started_at_iso=_utcnow_iso())

    jira = _load("jira_entities.json")
    issue = None
    if has_id:
        iid = issue_id.strip()
        for r in jira:
            if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("external_id") == iid:
                issue = r
                break
    else:
        ik = issue_key.strip()
        for r in jira:
            if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("key") == ik:
                issue = r
                break

    if not issue:
        _finalize_op(op["id"], status="failed", http_status=404, error_code="NOT_FOUND",
                     error_message="Issue not found in cache; remote worklog creation is not available in offline datastore backend.",
                     finished_at=_utcnow_iso())
        return _err("NOT_FOUND", "Issue not found", operation_id=op.get("id"))

    # Business rule: must not create worklogs when referenced issue is 'deleted' in the cache
    if issue.get("status") == "deleted":
        _finalize_op(op["id"], status="failed", http_status=409, error_code="CONFLICT",
                     error_message="Cannot add worklog: referenced issue is deleted in the cache.", finished_at=_utcnow_iso())
        return _err("CONFLICT", "Cannot add worklog: referenced issue is deleted in the cache", operation_id=op.get("id"))

    now = _utcnow_iso()
    worklog_external_id = str(int(time.time() * 1000) + 1)

    new_row = {
        "id": _gen_id("jira_ent"),
        "connection_id": connection_id,
        "entity_type": "worklog",
        "external_id": worklog_external_id,
        "key": None,
        "name": None,
        "parent_external_id": None,
        "project_external_id": issue.get("project_external_id"),
        "issue_external_id": issue.get("external_id"),
        "from_issue_external_id": None,
        "to_issue_external_id": None,
        "link_type": None,
        "status_category": None,
        "status_name": None,
        "sprint_state": None,
        "board_type": None,
        "assignee_account_id": None,
        "reporter_account_id": None,
        "summary": None,
        "description_text": None,
        "body_text": comment.strip() if isinstance(comment, str) and comment.strip() else None,
        "time_spent_seconds": time_spent_seconds,
        "started_at": started_at_iso,
        "attachment_filename": None,
        "attachment_mime_type": None,
        "attachment_size_bytes": None,
        "attachment_download_url": None,
        "remote_updated_at": now,
        "status": "active",
        "raw": {
            "id": worklog_external_id,
            "issueId": issue.get("external_id"),
            "issueKey": issue.get("key"),
            "timeSpentSeconds": time_spent_seconds,
            "comment": comment.strip() if isinstance(comment, str) and comment.strip() else None,
            "started": started_at_iso,
            "created": now,
        },
        "created_at": now,
        "updated_at": now,
    }
    jira.append(new_row)
    _save("jira_entities.json", jira)

    _finalize_op(op["id"], status="succeeded", http_status=201,
                 response_summary={"created_worklog_id": worklog_external_id, "issue_external_id": issue.get("external_id")},
                 affected_external_ids=[worklog_external_id], finished_at=_utcnow_iso())

    return {
        "operation_id": op.get("id"),
        "connection_id": connection_id,
        "issue": {"key": issue.get("key"), "id": issue.get("external_id")},
        "worklog": {
            "id": worklog_external_id,
            "time_spent_seconds": time_spent_seconds,
            "comment": comment.strip() if isinstance(comment, str) and comment.strip() else None,
            "started_at": started_at_iso,
            "created": now,
        },
    }

def jira_link_to_epic(connection_id, epic_key=None, epic_id=None, issue_key=None, issue_id=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    ops = _load("tool_operations.json")
    conns = _load("atlassian_connections.json")
    jira = _load("jira_entities.json")
    rels = _load("content_relations.json")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _log_base(status, http_status=None, error_code=None, error_message=None, response_summary=None, affected_domain=None, affected_entity_type=None, affected_external_ids=None, started_at=None, finished_at=None):
        op = {
            "id": _new_id("op"),
            "connection_id": connection_id if isinstance(connection_id, str) else "unknown",
            "tool_name": "jira_link_to_epic",
            "request": {
                "connection_id": connection_id,
                "epic_key": epic_key,
                "epic_id": epic_id,
                "issue_key": issue_key,
                "issue_id": issue_id,
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": affected_domain,
            "affected_entity_type": affected_entity_type,
            "affected_external_ids": affected_external_ids,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        ops.append(op)
        _save("tool_operations.json", ops)
        return op

    def _finalize(op_id, **fields):
        for r in ops:
            if r.get("id") == op_id:
                r.update(fields)
                r["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                break
        _save("tool_operations.json", ops)

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        op = _log_base("failed", error_code="validation_error", error_message="connection_id is missing or malformed")
        return _err("VALIDATION_ERROR", "connection_id is missing or malformed", operation_id=op["id"])
    if (epic_key is None or epic_key == "") and (epic_id is None or epic_id == ""):
        op = _log_base("failed", error_code="validation_error", error_message="Either epic_key or epic_id is required")
        return _err("VALIDATION_ERROR", "Either epic_key or epic_id is required", operation_id=op["id"])
    if (issue_key is None or issue_key == "") and (issue_id is None or issue_id == ""):
        op = _log_base("failed", error_code="validation_error", error_message="Either issue_key or issue_id is required")
        return _err("VALIDATION_ERROR", "Either issue_key or issue_id is required", operation_id=op["id"])
    for nm, v in (("epic_key", epic_key), ("epic_id", epic_id), ("issue_key", issue_key), ("issue_id", issue_id)):
        if v is not None and not isinstance(v, str):
            op = _log_base("failed", error_code="validation_error", error_message=f"{nm} must be a string")
            return _err("VALIDATION_ERROR", f"{nm} must be a string", operation_id=op["id"])

    # Active connection
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        op = _log_base("failed", error_code="not_found", error_message="connection not found")
        return _err("NOT_FOUND", "connection not found", operation_id=op["id"])
    if conn.get("status") != "active":
        op = _log_base("failed", error_code="unauthorized", error_message="connection is not active")
        return _err("UNAUTHORIZED", "connection is not active", operation_id=op["id"])

    # Rate limiting
    running = sum(1 for r in ops if r.get("connection_id") == connection_id and r.get("status") == "running")
    if running >= 10:
        op = _log_base("failed", error_code="rate_limited", error_message="Too many concurrent operations")
        return _err("RATE_LIMIT", "Too many concurrent operations", operation_id=op["id"])

    one_min_ago = now - datetime.timedelta(minutes=1)
    remote_calls = 0
    for r in ops:
        if r.get("connection_id") != connection_id:
            continue
        sa = r.get("started_at")
        if not sa:
            continue
        try:
            dt = datetime.datetime.fromisoformat(sa.replace("Z", "+00:00"))
        except Exception:
            continue
        if dt >= one_min_ago and r.get("status") in ("running", "succeeded", "failed", "cancelled"):
            remote_calls += 1
    if remote_calls >= 60:
        op = _log_base("failed", error_code="rate_limited", error_message="Remote API rate limit exceeded")
        return _err("RATE_LIMIT", "Remote API rate limit exceeded", operation_id=op["id"])

    op = _log_base("running", started_at=now_iso)

    # Permission check via scopes
    scopes = conn.get("scopes") if isinstance(conn.get("scopes"), list) else []
    scope_str = " ".join([str(s) for s in scopes]).lower()
    if not scopes or not any(k in scope_str for k in ("write", "edit", "jira")):
        _finalize(op["id"], status="failed", finished_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),
                  error_code="unauthorized", error_message="connection lacks permission to edit issues", http_status=403)
        return _err("UNAUTHORIZED", "connection lacks permission to edit issues", operation_id=op["id"])

    def _find_issue(by_id, by_key):
        row = None
        if by_id:
            row = next((e for e in jira if e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("external_id") == by_id), None)
        if not row and by_key:
            row = next((e for e in jira if e.get("connection_id") == connection_id and e.get("entity_type") == "issue" and e.get("key") == by_key), None)
        return row

    epic_row = _find_issue(epic_id, epic_key)
    if not epic_row:
        _finalize(op["id"], status="failed", finished_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),
                  error_code="not_found", error_message="epic not found", http_status=404)
        return _err("NOT_FOUND", "epic not found", operation_id=op["id"])
    issue_row = _find_issue(issue_id, issue_key)
    if not issue_row:
        _finalize(op["id"], status="failed", finished_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),
                  error_code="not_found", error_message="issue not found", http_status=404)
        return _err("NOT_FOUND", "issue not found", operation_id=op["id"])

    if epic_row.get("status") == "deleted" or issue_row.get("status") == "deleted":
        _finalize(op["id"], status="failed", finished_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),
                  error_code="invalid_transition", error_message="cannot link deleted issues", http_status=409)
        return _err("INVALID_TRANSITION", "cannot link deleted issues", operation_id=op["id"])

    issue_ext = issue_row.get("external_id")
    epic_ext = epic_row.get("external_id")

    # Update issue snapshot: parent_external_id used as epic link placeholder
    issue_row["parent_external_id"] = epic_ext
    issue_row["remote_updated_at"] = now_iso
    issue_row["updated_at"] = now_iso
    raw = issue_row.get("raw") if isinstance(issue_row.get("raw"), dict) else {}
    fields = raw.get("fields") if isinstance(raw.get("fields"), dict) else {}
    fields["epic"] = {"id": epic_ext, "key": epic_row.get("key")}
    raw["fields"] = fields
    issue_row["raw"] = raw

    # Reflect relationship changes in content_relations: mark previous jira_epic_of edges removed; add/activate current
    for r in rels:
        if r.get("connection_id") == connection_id and r.get("domain") == "jira" and r.get("relation_type") == "jira_epic_of" and r.get("to_entity_external_id") == issue_ext:
            if r.get("from_entity_external_id") != epic_ext and r.get("status") == "active":
                r["status"] = "removed"
                r["updated_at"] = now_iso

    existing = next((r for r in rels
                     if r.get("connection_id") == connection_id and r.get("domain") == "jira" and r.get("relation_type") == "jira_epic_of"
                     and r.get("from_entity_external_id") == epic_ext and r.get("to_entity_external_id") == issue_ext), None)
    if existing:
        if existing.get("status") != "active":
            existing["status"] = "active"
        existing["updated_at"] = now_iso
    else:
        rels.append({
            "id": _new_id("rel"),
            "connection_id": connection_id,
            "domain": "jira",
            "relation_type": "jira_epic_of",
            "from_entity_external_id": epic_ext,
            "to_entity_external_id": issue_ext,
            "from_entity_type": "issue",
            "to_entity_type": "issue",
            "status": "active",
            "raw": {"source": "jira_link_to_epic"},
            "created_at": now_iso,
            "updated_at": now_iso,
        })

    _save("jira_entities.json", jira)
    _save("content_relations.json", rels)

    finished = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _finalize(
        op["id"],
        status="succeeded",
        http_status=200,
        finished_at=finished,
        response_summary={"issue_external_id": issue_ext, "epic_external_id": epic_ext},
        affected_domain="jira",
        affected_entity_type="issue",
        affected_external_ids=[issue_ext, epic_ext],
        error_code=None,
        error_message=None,
    )

    return {
        "issue": issue_row.get("raw"),
        "operation": {"id": op["id"], "status": "succeeded", "latency_ms": int((time.time() - t0) * 1000)},
    }

def jira_create_issue_link(connection_id, link_type, inward_issue_key=None, inward_issue_id=None, outward_issue_key=None, outward_issue_id=None, comment=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "jira_create_issue_link"
    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _append_op(conn_id_for_log, status, http_status=None, error_code=None, error_message=None,
                   response_summary=None, affected_external_ids=None, started_at=None, finished_at=None):
        ops = _load("tool_operations.json")
        now = _utcnow_iso()
        row = {
            "id": _gen_id("op"),
            "connection_id": conn_id_for_log if isinstance(conn_id_for_log, str) else "unknown",
            "tool_name": tool_name,
            "request": {
                "connection_id": connection_id,
                "inward_issue_key": inward_issue_key,
                "inward_issue_id": inward_issue_id,
                "outward_issue_key": outward_issue_key,
                "outward_issue_id": outward_issue_id,
                "link_type": link_type,
                "comment": comment,
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": "jira",
            "affected_entity_type": "issue_link",
            "affected_external_ids": affected_external_ids,
            "started_at": started_at or now,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    def _finalize_op(op_id, **fields):
        ops = _load("tool_operations.json")
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                r.update(fields)
                r["updated_at"] = _utcnow_iso()
                _save("tool_operations.json", ops)
                return True
        return False

    def _find_active_connection(conn_id):
        for c in _load("atlassian_connections.json"):
            if isinstance(c, dict) and c.get("id") == conn_id and c.get("status") == "active":
                return c
        return None

    def _rate_limit_ok(conn_id):
        ops = _load("tool_operations.json")
        now = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(seconds=60)
        remote_calls = 0
        running = 0
        for r in ops:
            if not isinstance(r, dict) or r.get("connection_id") != conn_id:
                continue
            if r.get("status") == "running":
                running += 1
            created_at = r.get("created_at")
            if isinstance(created_at, str):
                try:
                    dt = datetime.datetime.fromisoformat(created_at.replace("Z", "+00:00"))
                except Exception:
                    dt = None
                if dt and dt.tzinfo and dt >= one_min_ago:
                    remote_calls += 1
        if running >= 10:
            return False, "RATE_LIMIT", "rate_limited", "Too many concurrent operations for this connection."
        if remote_calls >= 60:
            return False, "RATE_LIMIT", "rate_limited", "Remote call rate limit exceeded for this connection."
        return True, None, None, None

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="connection_id is malformed.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "connection_id is malformed", operation_id=op.get("id"))

    if not isinstance(link_type, str) or not link_type.strip():
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="link_type is required.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "link_type is required", operation_id=op.get("id"))

    in_has_key = isinstance(inward_issue_key, str) and inward_issue_key.strip() != ""
    in_has_id = isinstance(inward_issue_id, str) and inward_issue_id.strip() != ""
    out_has_key = isinstance(outward_issue_key, str) and outward_issue_key.strip() != ""
    out_has_id = isinstance(outward_issue_id, str) and outward_issue_id.strip() != ""

    if in_has_key and in_has_id:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="Provide exactly one of inward_issue_key or inward_issue_id.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "Provide exactly one of inward_issue_key or inward_issue_id", operation_id=op.get("id"))
    if out_has_key and out_has_id:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="Provide exactly one of outward_issue_key or outward_issue_id.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "Provide exactly one of outward_issue_key or outward_issue_id", operation_id=op.get("id"))
    if (not in_has_key and not in_has_id) or (not out_has_key and not out_has_id):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="Must provide an inward issue (key or id) and an outward issue (key or id).",
                        finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "Must provide an inward issue (key or id) and an outward issue (key or id)", operation_id=op.get("id"))

    conn = _find_active_connection(connection_id)
    if not conn:
        op = _append_op(connection_id, "failed", http_status=401, error_code="UNAUTHORIZED",
                        error_message="All reads/writes must be scoped to a valid atlassian_connections row with status='active'.",
                        finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "All reads/writes must be scoped to a valid atlassian_connections row with status='active'.", operation_id=op.get("id"))

    ok, limit_code, norm_code, limit_msg = _rate_limit_ok(connection_id)
    if not ok:
        op = _append_op(connection_id, "failed", http_status=429, error_code=norm_code, error_message=limit_msg, finished_at=_utcnow_iso())
        return _err(limit_code, limit_msg, operation_id=op.get("id"))

    op = _append_op(connection_id, "running", started_at=_utcnow_iso())

    jira = _load("jira_entities.json")

    def _resolve_issue_external_id(by_key, by_id):
        if by_id is not None:
            iid = by_id.strip()
            for r in jira:
                if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("external_id") == iid:
                    return r.get("external_id"), r.get("key"), r
        if by_key is not None:
            ik = by_key.strip()
            for r in jira:
                if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "issue" and r.get("key") == ik:
                    return r.get("external_id"), r.get("key"), r
        return None, None, None

    in_id, in_key, in_row = _resolve_issue_external_id(inward_issue_key if in_has_key else None, inward_issue_id if in_has_id else None)
    out_id, out_key, out_row = _resolve_issue_external_id(outward_issue_key if out_has_key else None, outward_issue_id if out_has_id else None)

    if not in_row or not out_row:
        _finalize_op(op["id"], status="failed", http_status=404, error_code="NOT_FOUND",
                     error_message="One or both issues not found in cache; remote link creation is not available in offline datastore backend.",
                     finished_at=_utcnow_iso())
        return _err("NOT_FOUND", "One or both issues not found", operation_id=op.get("id"))

    if in_id == out_id:
        _finalize_op(op["id"], status="failed", http_status=400, error_code="VALIDATION_ERROR",
                     error_message="inward and outward issues must be different.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "inward and outward issues must be different", operation_id=op.get("id"))

    # Idempotency: if link already exists active, return it
    existing = None
    for r in jira:
        if not isinstance(r, dict):
            continue
        if r.get("connection_id") == connection_id and r.get("entity_type") == "issue_link" and r.get("status") == "active":
            if r.get("from_issue_external_id") == in_id and r.get("to_issue_external_id") == out_id and r.get("link_type") == link_type.strip():
                existing = r
                break

    now = _utcnow_iso()
    affected = []

    if existing:
        link_external_id = existing.get("external_id")
        affected.append(link_external_id)
        _finalize_op(op["id"], status="succeeded", http_status=200,
                     response_summary={"issue_link_id": link_external_id, "idempotent": True},
                     affected_external_ids=affected, finished_at=_utcnow_iso())
        return {
            "operation_id": op.get("id"),
            "connection_id": connection_id,
            "issue_link": {
                "id": link_external_id,
                "type": link_type.strip(),
                "inward": {"id": in_id, "key": in_key},
                "outward": {"id": out_id, "key": out_key},
            },
            "idempotent": True,
        }

    link_external_id = str(int(time.time() * 1000) + 2)
    link_row = {
        "id": _gen_id("jira_ent"),
        "connection_id": connection_id,
        "entity_type": "issue_link",
        "external_id": link_external_id,
        "key": None,
        "name": None,
        "parent_external_id": None,
        "project_external_id": None,
        "issue_external_id": None,
        "from_issue_external_id": in_id,
        "to_issue_external_id": out_id,
        "link_type": link_type.strip(),
        "status_category": None,
        "status_name": None,
        "sprint_state": None,
        "board_type": None,
        "assignee_account_id": None,
        "reporter_account_id": None,
        "summary": None,
        "description_text": None,
        "body_text": comment.strip() if isinstance(comment, str) and comment.strip() else None,
        "time_spent_seconds": None,
        "started_at": None,
        "attachment_filename": None,
        "attachment_mime_type": None,
        "attachment_size_bytes": None,
        "attachment_download_url": None,
        "remote_updated_at": now,
        "status": "active",
        "raw": {
            "id": link_external_id,
            "type": link_type.strip(),
            "inwardIssueId": in_id,
            "outwardIssueId": out_id,
            "comment": comment.strip() if isinstance(comment, str) and comment.strip() else None,
            "created": now,
        },
        "created_at": now,
        "updated_at": now,
    }
    jira.append(link_row)
    _save("jira_entities.json", jira)
    affected.append(link_external_id)

    # Create content_relations edge only if link_type maps to supported semantic relations
    supported_map = {
        "epic": "jira_epic_of",
        "parent": "jira_parent_of",
    }
    relation_type = None
    lt = link_type.strip().lower()
    if "epic" in lt:
        relation_type = supported_map["epic"]
    elif "parent" in lt:
        relation_type = supported_map["parent"]

    if relation_type:
        rels = _load("content_relations.json")
        # upsert unique(connection_id, domain, relation_type, from_entity_external_id, to_entity_external_id)
        rel = None
        for e in rels:
            if not isinstance(e, dict):
                continue
            if e.get("connection_id") == connection_id and e.get("domain") == "jira" and e.get("relation_type") == relation_type and e.get("from_entity_external_id") == in_id and e.get("to_entity_external_id") == out_id:
                rel = e
                break
        if rel:
            if rel.get("status") != "active":
                rel["status"] = "active"
                rel["updated_at"] = now
            if rel.get("raw") is None:
                rel["raw"] = {}
            if isinstance(rel["raw"], dict):
                rel["raw"]["issue_link_id"] = link_external_id
            _save("content_relations.json", rels)
        else:
            new_rel = {
                "id": _gen_id("rel"),
                "connection_id": connection_id,
                "domain": "jira",
                "relation_type": relation_type,
                "from_entity_external_id": in_id,
                "to_entity_external_id": out_id,
                "from_entity_type": "issue",
                "to_entity_type": "issue",
                "status": "active",
                "raw": {"issue_link_id": link_external_id},
                "created_at": now,
                "updated_at": now,
            }
            rels.append(new_rel)
            _save("content_relations.json", rels)

    _finalize_op(op["id"], status="succeeded", http_status=201,
                 response_summary={"issue_link_id": link_external_id, "relation_type": relation_type},
                 affected_external_ids=affected, finished_at=_utcnow_iso())

    return {
        "operation_id": op.get("id"),
        "connection_id": connection_id,
        "issue_link": {
            "id": link_external_id,
            "type": link_type.strip(),
            "inward": {"id": in_id, "key": in_key},
            "outward": {"id": out_id, "key": out_key},
        },
        "created_relation_type": relation_type,
    }

def jira_transition_issue(connection_id, issue_key=None, issue_id=None, transition_id=None, transition_name=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "connection_id is invalid; expected ^atl_conn_[0-9A-Z]{18,}$")

    if issue_key is not None and (not isinstance(issue_key, str) or not issue_key.strip()):
        return _err("VALIDATION_ERROR", "issue_key must be a non-empty string when provided")
    if issue_id is not None and (not isinstance(issue_id, str) or not issue_id.strip()):
        return _err("VALIDATION_ERROR", "issue_id must be a non-empty string when provided")

    if (not issue_key or not str(issue_key).strip()) and (not issue_id or not str(issue_id).strip()):
        return _err("VALIDATION_ERROR", "Either issue_key or issue_id must be provided")

    if transition_id is not None and (not isinstance(transition_id, str) or not transition_id.strip()):
        return _err("VALIDATION_ERROR", "transition_id must be a non-empty string when provided")
    if transition_name is not None and (not isinstance(transition_name, str) or not transition_name.strip()):
        return _err("VALIDATION_ERROR", "transition_name must be a non-empty string when provided")

    if (not transition_id or not str(transition_id).strip()) and (not transition_name or not str(transition_name).strip()):
        return _err("VALIDATION_ERROR", "Either transition_id or transition_name must be provided")

    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id), None)

    ops = _load("tool_operations.json")

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _log_base(status, http_status=None, error_code=None, error_message=None, response_summary=None,
                  affected_external_ids=None, started_at=None, finished_at=None):
        op = {
            "id": _new_id("op"),
            "connection_id": connection_id,
            "tool_name": "jira_transition_issue",
            "request": {
                "connection_id": connection_id,
                "issue_key": issue_key,
                "issue_id": issue_id,
                "transition_id": transition_id,
                "transition_name": transition_name,
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": "jira",
            "affected_entity_type": "issue",
            "affected_external_ids": affected_external_ids,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("tool_operations.json", ops)
        return op

    if not conn or conn.get("status") != "active":
        _log_base(
            status="failed",
            http_status=401,
            error_code="unauthorized",
            error_message="Connection is missing or not active",
            response_summary={"latency_ms": int((time.time() - t0) * 1000)},
            affected_external_ids=[issue_id] if issue_id else None,
            started_at=now,
            finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        )
        return _err("UNAUTHORIZED", "Connection is invalid/expired/disabled")

    # Concurrency limit
    running = sum(1 for o in ops if o.get("connection_id") == connection_id and o.get("status") == "running")
    if running >= 10:
        _log_base(
            status="failed",
            http_status=429,
            error_code="rate_limited",
            error_message="Too many concurrent operations",
            response_summary={"latency_ms": int((time.time() - t0) * 1000)},
            affected_external_ids=[issue_id] if issue_id else None,
            started_at=now,
            finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        )
        return _err("RATE_LIMIT", "Too many concurrent operations for this connection_id")

    # Per-minute remote call limit proxy
    one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    recent_succeeded = [
        o for o in ops
        if o.get("connection_id") == connection_id
        and o.get("status") == "succeeded"
        and (o.get("started_at") or "") >= one_min_ago
    ]
    if len(recent_succeeded) >= 60:
        _log_base(
            status="failed",
            http_status=429,
            error_code="rate_limited",
            error_message="Remote call rate limit exceeded",
            response_summary={"latency_ms": int((time.time() - t0) * 1000)},
            affected_external_ids=[issue_id] if issue_id else None,
            started_at=now,
            finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        )
        return _err("RATE_LIMIT", "Remote call rate limit exceeded for this connection_id")

    started_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_running = _log_base(
        status="running",
        http_status=None,
        error_code=None,
        error_message=None,
        response_summary=None,
        affected_external_ids=[issue_id] if issue_id else None,
        started_at=started_at,
        finished_at=None,
    )

    jira = _load("jira_entities.json")

    # Resolve issue row(s)
    issue_by_id = None
    issue_by_key = None
    if issue_id:
        issue_by_id = next(
            (r for r in jira
             if r.get("connection_id") == connection_id
             and r.get("entity_type") == "issue"
             and r.get("external_id") == issue_id),
            None
        )
    if issue_key:
        issue_by_key = next(
            (r for r in jira
             if r.get("connection_id") == connection_id
             and r.get("entity_type") == "issue"
             and r.get("key") == issue_key),
            None
        )

    if issue_by_id and issue_by_key and issue_by_id.get("external_id") != issue_by_key.get("external_id"):
        op_running["status"] = "failed"
        op_running["http_status"] = 400
        op_running["error_code"] = "validation_error"
        op_running["error_message"] = "issue_key and issue_id refer to different issues"
        op_running["response_summary"] = {"latency_ms": int((time.time() - t0) * 1000)}
        op_running["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_running["updated_at"] = op_running["finished_at"]
        _save("tool_operations.json", ops)
        return _err("VALIDATION_ERROR", "issue_key and issue_id refer to different issues")

    issue = issue_by_id or issue_by_key
    if not issue:
        op_running["status"] = "failed"
        op_running["http_status"] = 404
        op_running["error_code"] = "not_found"
        op_running["error_message"] = "Issue not found in cache"
        op_running["response_summary"] = {"latency_ms": int((time.time() - t0) * 1000)}
        op_running["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_running["updated_at"] = op_running["finished_at"]
        _save("tool_operations.json", ops)
        return _err("NOT_FOUND", "Issue not found")

    issue_ext_id = issue.get("external_id")
    op_running["affected_external_ids"] = [issue_ext_id]

    # Validate transition against latest known transitions in issue.raw
    raw = issue.get("raw") if isinstance(issue.get("raw"), dict) else {}
    transitions = None
    if isinstance(raw, dict):
        # accept a few plausible cache locations
        for k in ("transitions", "_transitions", "available_transitions"):
            if isinstance(raw.get(k), list):
                transitions = raw.get(k)
                break

    if not transitions:
        # No cached transitions; cannot validate -> treat as failed per business rule (needs latest fetched).
        op_running["status"] = "failed"
        op_running["http_status"] = 409
        op_running["error_code"] = "invalid_transition"
        op_running["error_message"] = "No cached transitions available to validate requested transition"
        op_running["response_summary"] = {"latency_ms": int((time.time() - t0) * 1000)}
        op_running["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_running["updated_at"] = op_running["finished_at"]
        _save("tool_operations.json", ops)
        return _err("INVALID_TRANSITION", "No cached transitions available; fetch transitions before transitioning")

    def _match_transition(t):
        if not isinstance(t, dict):
            return False
        tid = t.get("id")
        tname = t.get("name")
        if transition_id and tid is not None and str(tid) == str(transition_id):
            return True
        if transition_name and tname is not None and str(tname).strip().lower() == str(transition_name).strip().lower():
            return True
        return False

    matched = next((t for t in transitions if _match_transition(t)), None)
    if not matched:
        op_running["status"] = "failed"
        op_running["http_status"] = 409
        op_running["error_code"] = "invalid_transition"
        op_running["error_message"] = "Requested transition not present in latest transitions"
        op_running["response_summary"] = {
            "latency_ms": int((time.time() - t0) * 1000),
            "available_transition_ids": [str(t.get("id")) for t in transitions if isinstance(t, dict) and t.get("id") is not None][:50],
            "available_transition_names": [str(t.get("name")) for t in transitions if isinstance(t, dict) and t.get("name") is not None][:50],
        }
        op_running["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        op_running["updated_at"] = op_running["finished_at"]
        _save("tool_operations.json", ops)
        return _err("INVALID_TRANSITION", "Requested transition is not available for this issue")

    # Apply transition "remote success" (offline): update issue status_name/status_category/raw
    new_status_name = None
    new_status_category = None
    if isinstance(matched, dict):
        to_obj = matched.get("to") if isinstance(matched.get("to"), dict) else None
        if isinstance(to_obj, dict):
            new_status_name = to_obj.get("name") or matched.get("to_status_name")
            cat = to_obj.get("statusCategory")
            if isinstance(cat, dict):
                new_status_category = cat.get("name") or cat.get("key")
            else:
                new_status_category = matched.get("to_status_category")
        else:
            new_status_name = matched.get("to_status_name")
            new_status_category = matched.get("to_status_category")

    # If no to-status info, still record transition applied in raw
    if not isinstance(raw, dict):
        raw = {}
        issue["raw"] = raw

    raw["last_transition_applied"] = {
        "id": matched.get("id") if isinstance(matched, dict) else None,
        "name": matched.get("name") if isinstance(matched, dict) else None,
        "applied_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
    }
    issue["remote_updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    issue["updated_at"] = issue["remote_updated_at"]
    if new_status_name is not None:
        issue["status_name"] = new_status_name
    if new_status_category is not None:
        issue["status_category"] = new_status_category

    _save("jira_entities.json", jira)

    finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_running["status"] = "succeeded"
    op_running["http_status"] = 204
    op_running["error_code"] = None
    op_running["error_message"] = None
    op_running["response_summary"] = {
        "issue_external_id": issue_ext_id,
        "issue_key": issue.get("key"),
        "transition_applied": {
            "id": str(matched.get("id")) if isinstance(matched, dict) and matched.get("id") is not None else None,
            "name": matched.get("name") if isinstance(matched, dict) else None,
        },
        "new_status_name": issue.get("status_name"),
        "new_status_category": issue.get("status_category"),
        "latency_ms": int((time.time() - t0) * 1000),
    }
    op_running["finished_at"] = finished_at
    op_running["updated_at"] = finished_at
    _save("tool_operations.json", ops)

    return {
        "connection_id": connection_id,
        "issue": issue,
        "transition": op_running["response_summary"]["transition_applied"],
        "operation_id": op_running["id"],
    }

def confluence_search(connection_id, query, query_type=None, space_key=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "connection_id is invalid; expected ^atl_conn_[0-9A-Z]{18,}$")
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query is required and must be a non-empty string")

    if query_type is None:
        query_type = "simple"
    if query_type not in ("simple", "cql"):
        return _err("VALIDATION_ERROR", "query_type must be one of: simple, cql")

    if sort is None:
        sort = "relevance"
    if sort not in ("relevance", "last_modified_desc", "last_modified_asc"):
        return _err("VALIDATION_ERROR", "sort must be one of: relevance, last_modified_desc, last_modified_asc")

    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if space_key is not None and (not isinstance(space_key, str) or not space_key.strip()):
        return _err("VALIDATION_ERROR", "space_key must be a non-empty string when provided")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")

    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id), None)

    ops = _load("tool_operations.json")

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"

    def _log(status, http_status=None, error_code=None, error_message=None, response_summary=None,
             started_at=None, finished_at=None, affected_external_ids=None, affected_entity_type=None):
        op = {
            "id": _new_id("op"),
            "connection_id": connection_id,
            "tool_name": "confluence_search",
            "request": {
                "connection_id": connection_id,
                "query": query,
                "query_type": query_type,
                "space_key": space_key,
                "limit": limit,
                "cursor": cursor,
                "sort": sort,
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": "confluence",
            "affected_entity_type": affected_entity_type,
            "affected_external_ids": affected_external_ids,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("tool_operations.json", ops)
        return op

    if not conn or conn.get("status") != "active":
        _log(
            status="failed",
            http_status=401,
            error_code="unauthorized",
            error_message="Connection is missing or not active",
            response_summary={"latency_ms": int((time.time() - t0) * 1000)},
            started_at=now,
            finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            affected_entity_type="page",
        )
        return _err("UNAUTHORIZED", "Connection is invalid/expired/disabled")

    running = sum(1 for o in ops if o.get("connection_id") == connection_id and o.get("status") == "running")
    if running >= 10:
        _log(
            status="failed",
            http_status=429,
            error_code="rate_limited",
            error_message="Too many concurrent operations",
            response_summary={"latency_ms": int((time.time() - t0) * 1000)},
            started_at=now,
            finished_at=datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            affected_entity_type="page",
        )
        return _err("RATE_LIMIT", "Too many concurrent operations for this connection_id")

    started_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_running = _log(status="running", started_at=started_at, affected_entity_type="page")

    # Cursor: base64(json({"offset": int}))
    offset = 0
    if cursor:
        try:
            payload = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(payload)
            if not isinstance(obj, dict) or not isinstance(obj.get("offset", 0), int) or obj.get("offset", 0) < 0:
                raise ValueError("bad cursor")
            offset = obj.get("offset", 0)
        except Exception:
            op_running["status"] = "failed"
            op_running["http_status"] = 400
            op_running["error_code"] = "validation_error"
            op_running["error_message"] = "Invalid cursor"
            op_running["response_summary"] = {"latency_ms": int((time.time() - t0) * 1000)}
            op_running["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            op_running["updated_at"] = op_running["finished_at"]
            _save("tool_operations.json", ops)
            return _err("VALIDATION_ERROR", "cursor is invalid")

    conf = _load("confluence_entities.json")

    q = query.strip().lower()
    sk = space_key.strip() if isinstance(space_key, str) else None

    candidates = [
        r for r in conf
        if r.get("connection_id") == connection_id
        and r.get("entity_type") in ("page", "comment")
        and r.get("status") in ("current", "archived")  # exclude deleted from search results
        and (sk is None or r.get("space_key") == sk)
    ]

    def _text(r):
        # searchable combined text
        return " ".join([
            str(r.get("title") or ""),
            str(r.get("body_text") or ""),
            str(r.get("external_id") or ""),
            str(r.get("space_key") or ""),
        ]).lower()

    matched = []
    if query_type == "simple":
        # all terms must match somewhere
        terms = [t for t in re.split(r"\s+", q) if t]
        for r in candidates:
            txt = _text(r)
            ok = True
            for term in terms:
                if term not in txt:
                    ok = False
                    break
            if ok:
                matched.append(r)
    else:
        # "cql" offline approximation: if it contains space=KEY enforce it; otherwise substring match on remainder
        cql = q
        cql_space = None
        m = re.search(r"\bspace\s*=\s*([a-z0-9_-]+)\b", cql, flags=re.IGNORECASE)
        if m:
            cql_space = m.group(1)
        for r in candidates:
            if cql_space and (r.get("space_key") or "").lower() != cql_space.lower():
                continue
            if cql in _text(r):
                matched.append(r)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        # expect ISO with Z
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _relevance_score(r):
        txt = _text(r)
        # crude: count occurrences of full query and terms
        score = 0
        score -= txt.count(q) * 5
        for term in [t for t in re.split(r"\s+", q) if t]:
            score -= txt.count(term)
        # title matches more important
        score -= ((r.get("title") or "").lower().count(q) * 10)
        return score

    if sort == "relevance":
        matched.sort(key=lambda r: (_relevance_score(r), (r.get("title") or ""), str(r.get("external_id") or "")))
    elif sort == "last_modified_desc":
        matched.sort(key=lambda r: (_parse_dt(r.get("remote_updated_at")) or datetime.datetime.min), reverse=True)
    else:  # last_modified_asc
        matched.sort(key=lambda r: (_parse_dt(r.get("remote_updated_at")) or datetime.datetime.min))

    total = len(matched)
    page = matched[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    affected_ids = [r.get("external_id") for r in page if r.get("external_id") is not None]

    finished_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    op_running["status"] = "succeeded"
    op_running["http_status"] = 200
    op_running["error_code"] = None
    op_running["error_message"] = None
    op_running["affected_entity_type"] = "page"  # primary affected type for search
    op_running["affected_external_ids"] = affected_ids
    op_running["response_summary"] = {
        "query": query,
        "query_type": query_type,
        "space_key": space_key,
        "sort": sort,
        "returned": len(page),
        "total_matched": total,
        "next_cursor": next_cursor,
        "latency_ms": int((time.time() - t0) * 1000),
    }
    op_running["finished_at"] = finished_at
    op_running["updated_at"] = finished_at
    _save("tool_operations.json", ops)

    return {
        "results": [
            {
                "type": r.get("entity_type"),
                "id": r.get("external_id"),
                "space_key": r.get("space_key"),
                "title": r.get("title"),
                "excerpt": (r.get("body_text") or "")[:280] if isinstance(r.get("body_text"), str) else None,
                "version_number": r.get("version_number"),
                "remote_updated_at": r.get("remote_updated_at"),
                "raw": r.get("raw"),
            }
            for r in page
        ],
        "limit": limit,
        "cursor": next_cursor,
        "has_more": has_more,
        "total": total,
        "operation_id": op_running["id"],
    }

def confluence_get_page(connection_id, page_id, include_body=None, body_format=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "confluence_get_page"
    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _append_op(conn_id_for_log, status, http_status=None, error_code=None, error_message=None,
                   response_summary=None, affected_external_ids=None, started_at=None, finished_at=None):
        ops = _load("tool_operations.json")
        now = _utcnow_iso()
        row = {
            "id": _gen_id("op"),
            "connection_id": conn_id_for_log if isinstance(conn_id_for_log, str) else "unknown",
            "tool_name": tool_name,
            "request": {"connection_id": connection_id, "page_id": page_id, "include_body": include_body, "body_format": body_format},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": "confluence",
            "affected_entity_type": "page",
            "affected_external_ids": affected_external_ids,
            "started_at": started_at or now,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    def _find_active_connection(conn_id):
        for c in _load("atlassian_connections.json"):
            if isinstance(c, dict) and c.get("id") == conn_id and c.get("status") == "active":
                return c
        return None

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="connection_id is malformed.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "connection_id is malformed", operation_id=op.get("id"))
    if not isinstance(page_id, str) or not page_id.strip():
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="page_id is required.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "page_id is required", operation_id=op.get("id"))
    if include_body is not None and not isinstance(include_body, bool):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="include_body must be a boolean when provided.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "include_body must be a boolean when provided", operation_id=op.get("id"))
    if body_format is not None:
        if include_body is not True:
            op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                            error_message="body_format can only be set when include_body is true.", finished_at=_utcnow_iso())
            return _err("VALIDATION_ERROR", "body_format can only be set when include_body is true", operation_id=op.get("id"))
        if body_format not in ("storage", "atlas_doc_format", "view"):
            op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                            error_message="body_format must be one of: storage, atlas_doc_format, view.", finished_at=_utcnow_iso())
            return _err("VALIDATION_ERROR", "body_format must be one of: storage, atlas_doc_format, view", operation_id=op.get("id"))

    conn = _find_active_connection(connection_id)
    if not conn:
        op = _append_op(connection_id, "failed", http_status=401, error_code="UNAUTHORIZED",
                        error_message="All reads/writes must be scoped to a valid atlassian_connections row with status='active'.",
                        finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "All reads/writes must be scoped to a valid atlassian_connections row with status='active'.", operation_id=op.get("id"))

    # Serve from cache
    ents = _load("confluence_entities.json")
    page = None
    pid = page_id.strip()
    for r in ents:
        if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "page" and r.get("external_id") == pid:
            page = r
            break

    op = _append_op(connection_id, "succeeded", http_status=200,
                    response_summary={"cache_hit": bool(page), "page_id": pid},
                    affected_external_ids=[pid] if page else [], finished_at=_utcnow_iso())

    if not page:
        return {"operation_id": op.get("id"), "connection_id": connection_id, "page": None}

    out = {
        "operation_id": op.get("id"),
        "connection_id": connection_id,
        "page": {
            "id": page.get("external_id"),
            "title": page.get("title"),
            "space_key": page.get("space_key"),
            "status": page.get("status"),
            "version_number": page.get("version_number"),
            "updated_at": page.get("remote_updated_at") or page.get("updated_at"),
        }
    }
    if include_body:
        bf = body_format or "storage"
        body_val = None
        raw = page.get("raw")
        if isinstance(raw, dict):
            # best-effort: extract typical Confluence shapes
            body_obj = raw.get("body")
            if isinstance(body_obj, dict):
                rep = body_obj.get(bf)
                if isinstance(rep, dict):
                    body_val = rep.get("value")
        if body_val is None:
            body_val = page.get("body_text")
        out["page"]["body"] = {"format": bf, "value": body_val}
    return out

def confluence_get_page_children(connection_id, page_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "confluence_get_page_children"
    started_ts = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(random.choice(alphabet) for _ in range(24))

    def _encode_cursor(i):
        return base64.urlsafe_b64encode(f"i:{i}".encode("utf-8")).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        pad = "=" * (-len(c) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
            if not raw.startswith("i:"):
                return None
            return int(raw[2:])
        except Exception:
            return None

    def _write_op(connection_id_for_log, status, http_status=None, error_code=None, error_message=None,
                  response_summary=None, affected_external_ids=None):
        ops = _load("tool_operations.json")
        op_id = _gen_id("op")
        row = {
            "id": op_id,
            "connection_id": connection_id_for_log,
            "tool_name": tool_name,
            "request": {"connection_id": connection_id, "page_id": page_id, "limit": limit, "cursor": cursor},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": "confluence",
            "affected_entity_type": "page",
            "affected_external_ids": affected_external_ids,
            "started_at": now,
            "finished_at": _iso_now(),
            "created_at": now,
            "updated_at": _iso_now(),
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return op_id

    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id or ""):
        _write_op(connection_id if isinstance(connection_id, str) else "unknown", "failed",
                  http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id is malformed.")
        return _err("VALIDATION_ERROR", "connection_id is malformed.")
    if not isinstance(page_id, str) or not page_id.strip():
        _write_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message="page_id is missing/empty.")
        return _err("VALIDATION_ERROR", "page_id is missing/empty.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _write_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 200.")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _write_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message="cursor must be a string.")
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if conn is None:
        _write_op(connection_id, "failed", http_status=404, error_code="NOT_FOUND", error_message="Connection not found.")
        return _err("NOT_FOUND", "Connection not found.")
    if conn.get("status") != "active":
        _write_op(connection_id, "failed", http_status=401, error_code="UNAUTHORIZED",
                  error_message="All reads/writes must be scoped to an active atlassian_connections row (status='active').")
        return _err("UNAUTHORIZED", "Connection is not active; business rule forbids operations unless status='active'.")

    # rate limit (read)
    ops = _load("tool_operations.json")
    running = [o for o in ops if isinstance(o, dict) and o.get("connection_id") == connection_id and o.get("status") == "running"]
    if len(running) >= 10:
        _write_op(connection_id, "failed", http_status=429, error_code="rate_limited",
                  error_message="Too many concurrent operations for this connection_id.")
        return _err("RATE_LIMIT", "Too many concurrent operations for this connection_id.", error_code="rate_limited")
    one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    recent = [
        o for o in ops
        if isinstance(o, dict)
        and o.get("connection_id") == connection_id
        and isinstance(o.get("started_at"), str)
        and o.get("started_at") >= one_min_ago
        and o.get("status") in ("succeeded", "failed", "running")
    ]
    if len(recent) >= 60:
        _write_op(connection_id, "failed", http_status=429, error_code="rate_limited",
                  error_message="Remote call rate limit exceeded for this connection_id (60/min).")
        return _err("RATE_LIMIT", "Remote call rate limit exceeded for this connection_id.", error_code="rate_limited")

    # Use relations if available
    rels = _load("content_relations.json")
    conf = _load("confluence_entities.json")

    # Ensure parent page exists (or at least is known) when possible; but empty children list is valid.
    parent = next((p for p in conf if isinstance(p, dict) and p.get("connection_id") == connection_id and p.get("entity_type") == "page" and p.get("external_id") == page_id), None)
    if parent is not None and parent.get("status") == "deleted":
        _write_op(connection_id, "failed", http_status=404, error_code="NOT_FOUND", error_message="Page not found.")
        return _err("NOT_FOUND", "Page not found.")

    children_edges = [
        e for e in rels
        if isinstance(e, dict)
        and e.get("connection_id") == connection_id
        and e.get("domain") == "confluence"
        and e.get("relation_type") == "confluence_parent_of"
        and e.get("status") == "active"
        and e.get("from_entity_external_id") == page_id
    ]
    child_ids = [e.get("to_entity_external_id") for e in children_edges if isinstance(e.get("to_entity_external_id"), str)]

    # Map to child pages (only current/archived, not deleted)
    child_pages = []
    for cid in child_ids:
        p = next((r for r in conf if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "page" and r.get("external_id") == cid), None)
        if p and p.get("status") != "deleted":
            child_pages.append(p)

    # stable sort by title then id
    child_pages.sort(key=lambda r: ((r.get("title") or "").lower(), r.get("external_id") or ""))

    offset = _decode_cursor(cursor)
    if offset is None or offset < 0:
        _write_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message="cursor is invalid.")
        return _err("VALIDATION_ERROR", "cursor is invalid.")

    total = len(child_pages)
    page_slice = child_pages[offset:offset + limit]
    next_offset = offset + len(page_slice)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    results = [{
        "id": p.get("external_id"),
        "title": p.get("title"),
        "space_key": p.get("space_key"),
        "status": p.get("status"),
        "version_number": p.get("version_number"),
        "remote_updated_at": p.get("remote_updated_at"),
    } for p in page_slice]

    _write_op(connection_id, "succeeded", http_status=200,
              response_summary={"total": total, "returned": len(results), "page_id": page_id},
              affected_external_ids=[page_id] + [r["id"] for r in results])

    return {
        "results": results,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "next_cursor": next_cursor,
        "has_more": has_more,
        "operation": {"tool_name": tool_name, "connection_id": connection_id, "latency_ms": int((time.time() - started_ts) * 1000)},
    }

def confluence_get_page_ancestors(connection_id, page_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "confluence_get_page_ancestors"
    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _append_op(conn_id_for_log, status, http_status=None, error_code=None, error_message=None,
                   response_summary=None, affected_external_ids=None, started_at=None, finished_at=None):
        ops = _load("tool_operations.json")
        now = _utcnow_iso()
        row = {
            "id": _gen_id("op"),
            "connection_id": conn_id_for_log if isinstance(conn_id_for_log, str) else "unknown",
            "tool_name": tool_name,
            "request": {"connection_id": connection_id, "page_id": page_id},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": "confluence",
            "affected_entity_type": "page",
            "affected_external_ids": affected_external_ids,
            "started_at": started_at or now,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    def _find_active_connection(conn_id):
        for c in _load("atlassian_connections.json"):
            if isinstance(c, dict) and c.get("id") == conn_id and c.get("status") == "active":
                return c
        return None

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="connection_id is malformed.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "connection_id is malformed", operation_id=op.get("id"))
    if not isinstance(page_id, str) or not page_id.strip():
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="page_id is required.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "page_id is required", operation_id=op.get("id"))

    conn = _find_active_connection(connection_id)
    if not conn:
        op = _append_op(connection_id, "failed", http_status=401, error_code="UNAUTHORIZED",
                        error_message="All reads/writes must be scoped to a valid atlassian_connections row with status='active'.",
                        finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "All reads/writes must be scoped to a valid atlassian_connections row with status='active'.", operation_id=op.get("id"))

    pid = page_id.strip()
    rels = _load("content_relations.json")
    ents = _load("confluence_entities.json")

    # Build parent map from active confluence_parent_of edges: from=parent, to=child
    parent_of = {}
    for e in rels:
        if not isinstance(e, dict):
            continue
        if e.get("connection_id") != connection_id or e.get("domain") != "confluence":
            continue
        if e.get("relation_type") != "confluence_parent_of" or e.get("status") != "active":
            continue
        parent_of[e.get("to_entity_external_id")] = e.get("from_entity_external_id")

    # Follow chain
    ancestors_ids = []
    seen = set()
    cur = pid
    while cur in parent_of:
        par = parent_of.get(cur)
        if not isinstance(par, str) or not par or par in seen:
            break
        seen.add(par)
        ancestors_ids.append(par)
        cur = par

    # Build summaries (ordered root->parent) like Confluence does; our chain is child->root so reverse
    ancestors_ids_rev = list(reversed(ancestors_ids))

    def _page_summary(external_id):
        for r in ents:
            if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "page" and r.get("external_id") == external_id:
                return {"id": external_id, "title": r.get("title"), "space_key": r.get("space_key"), "status": r.get("status")}
        return {"id": external_id, "title": None, "space_key": None, "status": None}

    ancestors = [_page_summary(x) for x in ancestors_ids_rev]

    op = _append_op(connection_id, "succeeded", http_status=200,
                    response_summary={"ancestors_count": len(ancestors), "page_id": pid},
                    affected_external_ids=[pid] + ancestors_ids_rev, finished_at=_utcnow_iso())

    return {
        "operation_id": op.get("id"),
        "connection_id": connection_id,
        "page_id": pid,
        "ancestors": ancestors,
        "meta": {"count": len(ancestors)},
    }

def confluence_get_comments(connection_id, page_id, limit=None, cursor=None, include_body=None, body_format=None, **_extra):
    import json, os, datetime, re, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    tool_name = "confluence_get_comments"
    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _enc(i):
        return base64.urlsafe_b64encode(f"i:{i}".encode("utf-8")).decode("ascii").rstrip("=")

    def _dec(c):
        if c is None:
            return 0, None
        if not isinstance(c, str) or not c:
            return None, "cursor must be a string when provided."
        pad = "=" * (-len(c) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
            if not raw.startswith("i:"):
                return None, "cursor is invalid."
            return int(raw[2:]), None
        except Exception:
            return None, "cursor is invalid."

    def _append_op(connection_id_for_log, status, http_status=None, error_code=None, error_message=None,
                   response_summary=None, affected_external_ids=None, started_at=None, finished_at=None):
        ops = _load("tool_operations.json")
        now = _utcnow_iso()
        row = {
            "id": _gen_id("op"),
            "connection_id": connection_id_for_log if isinstance(connection_id_for_log, str) else "unknown",
            "tool_name": tool_name,
            "request": {"connection_id": connection_id, "page_id": page_id, "limit": limit, "cursor": cursor, "include_body": include_body, "body_format": body_format},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": "confluence",
            "affected_entity_type": "comment",
            "affected_external_ids": affected_external_ids,
            "started_at": started_at or now,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    def _finalize_op(op_id, **fields):
        ops = _load("tool_operations.json")
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                r.update(fields)
                r["updated_at"] = _utcnow_iso()
                _save("tool_operations.json", ops)
                return True
        return False

    # validate
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message="connection_id is malformed.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "connection_id is malformed.", operation_id=op["id"])
    if not isinstance(page_id, str) or not page_id.strip():
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message="page_id is required and must be non-empty.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "page_id is required and must be non-empty.", operation_id=op["id"])
    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 200.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", operation_id=op["id"])
    if include_body is not None and not isinstance(include_body, bool):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message="include_body must be boolean when provided.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "include_body must be boolean when provided.", operation_id=op["id"])
    if body_format is not None:
        if not isinstance(body_format, str) or body_format not in ("storage", "atlas_doc_format", "view"):
            op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message="body_format must be one of: storage, atlas_doc_format, view.", finished_at=_utcnow_iso())
            return _err("VALIDATION_ERROR", "body_format must be one of: storage, atlas_doc_format, view.", operation_id=op["id"])
        if not include_body:
            op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message="body_format can only be provided when include_body is true.", finished_at=_utcnow_iso())
            return _err("VALIDATION_ERROR", "body_format can only be provided when include_body is true.", operation_id=op["id"])

    offset, cerr = _dec(cursor)
    if cerr:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message=cerr, finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", cerr, operation_id=op["id"])
    if offset is None or offset < 0:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR", error_message="cursor is invalid.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "cursor is invalid.", operation_id=op["id"])

    op = _append_op(connection_id, "running", started_at=_utcnow_iso())
    op_id = op["id"]

    # auth
    conns = _load("atlassian_connections.json")
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        _finalize_op(op_id, status="failed", http_status=404, error_code="NOT_FOUND", error_message="connection_id not found.", finished_at=_utcnow_iso())
        return _err("NOT_FOUND", "connection_id not found.", operation_id=op_id)
    if conn.get("status") != "active":
        _finalize_op(op_id, status="failed", http_status=401, error_code="UNAUTHORIZED", error_message="All reads/writes must be scoped to an active connection (status='active').", finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "All reads/writes must be scoped to an active connection (status='active').", operation_id=op_id)

    # rate limit checks
    ops_all = _load("tool_operations.json")
    running_count = sum(1 for o in ops_all if isinstance(o, dict) and o.get("connection_id") == connection_id and o.get("status") == "running")
    if running_count > 10:
        _finalize_op(op_id, status="failed", http_status=429, error_code="rate_limited", error_message="Too many concurrent operations for this connection_id.", finished_at=_utcnow_iso())
        return _err("RATE_LIMIT", "Too many concurrent operations for this connection_id.", operation_id=op_id)
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    cutoff = (now_dt - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    recent = [o for o in ops_all if isinstance(o, dict) and o.get("connection_id") == connection_id and isinstance(o.get("started_at"), str) and o.get("started_at") >= cutoff]
    if len(recent) > 60:
        _finalize_op(op_id, status="failed", http_status=429, error_code="rate_limited", error_message="Remote call rate limit exceeded for this connection_id (60/min).", finished_at=_utcnow_iso())
        return _err("RATE_LIMIT", "Remote call rate limit exceeded for this connection_id (60/min).", operation_id=op_id)

    conf = _load("confluence_entities.json")
    # comments by parent_external_id matching page_id
    comments = [e for e in conf if isinstance(e, dict) and e.get("connection_id") == connection_id and e.get("entity_type") == "comment" and e.get("parent_external_id") == page_id]

    # stable ordering: by remote_updated_at then external_id
    def _k(e):
        ru = e.get("remote_updated_at") if isinstance(e.get("remote_updated_at"), str) else ""
        return (ru, e.get("external_id") or "")
    comments.sort(key=_k)

    total = len(comments)
    page = comments[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _enc(next_offset) if has_more else None

    fmt = body_format or "storage"
    items = []
    for c in page:
        item = {
            "id": c.get("external_id"),
            "status": c.get("status"),
            "page_id": c.get("parent_external_id"),
            "space_key": c.get("space_key"),
            "remote_updated_at": c.get("remote_updated_at"),
        }
        if include_body:
            raw = c.get("raw") if isinstance(c.get("raw"), dict) else {}
            item["body"] = {"format": fmt, "value": c.get("body_text") if c.get("body_text") is not None else raw.get("body")}
        items.append(item)

    _finalize_op(op_id, status="succeeded", http_status=200, response_summary={"page_id": page_id, "returned": len(items), "total": total}, affected_external_ids=[page_id], finished_at=_utcnow_iso())
    return {
        "operation_id": op_id,
        "results": items,
        "limit": limit,
        "cursor": next_cursor,
        "has_more": has_more,
        "total": total,
    }

def confluence_update_page(connection_id, page_id, version_number, title=None, body=None, body_format=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
