    if not isinstance(version_number, int) or version_number < 1:
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="version_number must be an integer >= 1.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "version_number must be an integer >= 1", operation_id=op.get("id"))
    if body_format is not None:
        if body is None:
            op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                            error_message="body_format cannot be provided without body.", finished_at=_utcnow_iso())
            return _err("VALIDATION_ERROR", "body_format cannot be provided without body", operation_id=op.get("id"))
        if body_format not in ("storage", "atlas_doc_format"):
            op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                            error_message="body_format must be one of: storage, atlas_doc_format.", finished_at=_utcnow_iso())
            return _err("VALIDATION_ERROR", "body_format must be one of: storage, atlas_doc_format", operation_id=op.get("id"))

    conn = _find_active_connection(connection_id)
    if not conn:
        op = _append_op(connection_id, "failed", http_status=401, error_code="UNAUTHORIZED",
                        error_message="All reads/writes must be scoped to a valid atlassian_connections row with status='active'.",
                        finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "All reads/writes must be scoped to a valid atlassian_connections row with status='active'.", operation_id=op.get("id"))

    ok, limit_code, norm_code, limit_msg = _rate_limit_ok(connection_id)
    if not ok:
        op = _append_op(connection_id, "failed", http_status=429, error_code=norm_code, error_message=limit_msg, finished_at=_utcnow_iso())
        return _err(limit_code, limit_msg, operation_id=op.get("id"))

    op = _append_op(connection_id, "running", started_at=_utcnow_iso())

    ents = _load("confluence_entities.json")
    pid = page_id.strip()
    page = None
    for r in ents:
        if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "page" and r.get("external_id") == pid:
            page = r
            break

    if not page:
        _finalize_op(op["id"], status="failed", http_status=404, error_code="NOT_FOUND",
                     error_message="Page not found in cache; remote update is not available in offline datastore backend.",
                     finished_at=_utcnow_iso())
        return _err("NOT_FOUND", "Page not found", operation_id=op.get("id"))

    # Business rule: reject updates if cached status is deleted
    if page.get("status") == "deleted":
        _finalize_op(op["id"], status="failed", http_status=409, error_code="CONFLICT",
                     error_message="Cannot update a page that is deleted in the cache.", finished_at=_utcnow_iso())
        return _err("CONFLICT", "Cannot update a page that is deleted in the cache", operation_id=op.get("id"))

    # Apply update
    now = _utcnow_iso()
    page["version_number"] = version_number
    if title is not None:
        page["title"] = title
    if body is not None:
        page["body_text"] = body  # store plain-text-ish; representation unknown
        if isinstance(page.get("raw"), dict):
            raw = page["raw"]
        else:
            raw = {}
        fmt = body_format or "storage"
        if "body" not in raw or not isinstance(raw.get("body"), dict):
            raw["body"] = {}
        if fmt not in raw["body"] or not isinstance(raw["body"].get(fmt), dict):
            raw["body"][fmt] = {}
        raw["body"][fmt]["value"] = body
        raw["body"][fmt]["representation"] = fmt
        page["raw"] = raw
    page["remote_updated_at"] = now
    page["updated_at"] = now

    _save("confluence_entities.json", ents)

    _finalize_op(op["id"], status="succeeded", http_status=200,
                 response_summary={"page_id": pid, "version_number": version_number},
                 affected_external_ids=[pid], finished_at=_utcnow_iso())

    return {
        "operation_id": op.get("id"),
        "connection_id": connection_id,
        "page": {
            "id": pid,
            "title": page.get("title"),
            "status": page.get("status"),
            "version_number": page.get("version_number"),
            "body_text": page.get("body_text"),
            "updated_at": page.get("remote_updated_at") or page.get("updated_at"),
        }
    }

def confluence_delete_page(connection_id, page_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "confluence_delete_page"
    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _append_op(conn_id_for_log, status, http_status=None, error_code=None, error_message=None,
                   response_summary=None, affected_external_ids=None, started_at=None, finished_at=None):
        ops = _load("tool_operations.json")
        now = _utcnow_iso()
        row = {
            "id": _gen_id("op"),
            "connection_id": conn_id_for_log if isinstance(conn_id_for_log, str) else "unknown",
            "tool_name": tool_name,
            "request": {"connection_id": connection_id, "page_id": page_id},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": "confluence",
            "affected_entity_type": "page",
            "affected_external_ids": affected_external_ids,
            "started_at": started_at or now,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    def _finalize_op(op_id, **fields):
        ops = _load("tool_operations.json")
        for r in ops:
            if isinstance(r, dict) and r.get("id") == op_id:
                r.update(fields)
                r["updated_at"] = _utcnow_iso()
                _save("tool_operations.json", ops)
                return True
        return False

    def _find_active_connection(conn_id):
        for c in _load("atlassian_connections.json"):
            if isinstance(c, dict) and c.get("id") == conn_id and c.get("status") == "active":
                return c
        return None

    def _rate_limit_ok(conn_id):
        ops = _load("tool_operations.json")
        now = datetime.datetime.now(datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(seconds=60)
        remote_calls = 0
        running = 0
        for r in ops:
            if not isinstance(r, dict) or r.get("connection_id") != conn_id:
                continue
            if r.get("status") == "running":
                running += 1
            created_at = r.get("created_at")
            if isinstance(created_at, str):
                try:
                    dt = datetime.datetime.fromisoformat(created_at.replace("Z", "+00:00"))
                except Exception:
                    dt = None
                if dt and dt.tzinfo and dt >= one_min_ago:
                    remote_calls += 1
        if running >= 10:
            return False, "RATE_LIMIT", "rate_limited", "Too many concurrent operations for this connection."
        if remote_calls >= 60:
            return False, "RATE_LIMIT", "rate_limited", "Remote call rate limit exceeded for this connection."
        return True, None, None, None

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="connection_id is malformed.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "connection_id is malformed", operation_id=op.get("id"))
    if not isinstance(page_id, str) or not page_id.strip():
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="page_id is required.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "page_id is required", operation_id=op.get("id"))

    conn = _find_active_connection(connection_id)
    if not conn:
        op = _append_op(connection_id, "failed", http_status=401, error_code="UNAUTHORIZED",
                        error_message="All reads/writes must be scoped to a valid atlassian_connections row with status='active'.",
                        finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "All reads/writes must be scoped to a valid atlassian_connections row with status='active'.", operation_id=op.get("id"))

    ok, limit_code, norm_code, limit_msg = _rate_limit_ok(connection_id)
    if not ok:
        op = _append_op(connection_id, "failed", http_status=429, error_code=norm_code, error_message=limit_msg, finished_at=_utcnow_iso())
        return _err(limit_code, limit_msg, operation_id=op.get("id"))

    op = _append_op(connection_id, "running", started_at=_utcnow_iso())

    pid = page_id.strip()
    ents = _load("confluence_entities.json")
    page = None
    for r in ents:
        if isinstance(r, dict) and r.get("connection_id") == connection_id and r.get("entity_type") == "page" and r.get("external_id") == pid:
            page = r
            break

    if not page:
        _finalize_op(op["id"], status="failed", http_status=404, error_code="NOT_FOUND",
                     error_message="Page not found in cache; remote delete is not available in offline datastore backend.",
                     finished_at=_utcnow_iso())
        return _err("NOT_FOUND", "Page not found", operation_id=op.get("id"))

    # Idempotent: if already deleted, succeed
    now = _utcnow_iso()
    changed = False
    if page.get("status") != "deleted":
        # lifecycle: current/archived -> deleted
        page["status"] = "deleted"
        page["updated_at"] = now
        page["remote_updated_at"] = now
        changed = True
        _save("confluence_entities.json", ents)

    # Mark outgoing/incoming relations removed
    rels = _load("content_relations.json")
    rel_changed = False
    for e in rels:
        if not isinstance(e, dict):
            continue
        if e.get("connection_id") != connection_id or e.get("domain") != "confluence":
            continue
        if e.get("relation_type") != "confluence_parent_of":
            continue
        if e.get("from_entity_external_id") == pid or e.get("to_entity_external_id") == pid:
            if e.get("status") != "removed":
                e["status"] = "removed"
                e["updated_at"] = now
                rel_changed = True
    if rel_changed:
        _save("content_relations.json", rels)

    _finalize_op(op["id"], status="succeeded", http_status=204,
                 response_summary={"deleted": True, "page_id": pid, "idempotent": not changed},
                 affected_external_ids=[pid], finished_at=_utcnow_iso())

    return {
        "operation_id": op.get("id"),
        "connection_id": connection_id,
        "deleted": True,
        "page_id": pid,
        "idempotent": not changed,
    }

def atlassian_get_caller(authorization, connection_id=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "atlassian_get_caller"
    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _parse_bearer(h):
        if not isinstance(h, str) or not h.strip():
            return None
        if not h.lower().startswith("bearer "):
            return None
        tok = h.split(" ", 1)[1].strip()
        return tok or None

    def _append_op(conn_id_for_log, status, http_status=None, error_code=None, error_message=None,
                   response_summary=None, started_at=None, finished_at=None):
        ops = _load("tool_operations.json")
        now = _utcnow_iso()
        row = {
            "id": _gen_id("op"),
            "connection_id": conn_id_for_log if isinstance(conn_id_for_log, str) else "unknown",
            "tool_name": tool_name,
            "request": {"authorization": "Bearer ***", "connection_id": connection_id},
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": None,
            "affected_entity_type": None,
            "affected_external_ids": None,
            "started_at": started_at or now,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    token = _parse_bearer(authorization)
    if token is None:
        op = _append_op("unknown", "failed", http_status=401, error_code="UNAUTHORIZED",
                        error_message="Invalid authorization; expected 'Bearer <token>'.", finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "Invalid authorization; expected 'Bearer <token>'.", operation_id=op.get("id"))

    # No credential store in this schema; treat any bearer token as valid and return accessible connections.
    conns = _load("atlassian_connections.json")
    if connection_id is not None:
        if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
            op = _append_op("unknown", "failed", http_status=400, error_code="VALIDATION_ERROR",
                            error_message="connection_id is malformed.", finished_at=_utcnow_iso())
            return _err("VALIDATION_ERROR", "connection_id is malformed", operation_id=op.get("id"))

    accessible = [c for c in conns if isinstance(c, dict)]
    if not accessible:
        op = _append_op("unknown", "failed", http_status=403, error_code="UNAUTHORIZED",
                        error_message="Credential is valid but has no access to any Atlassian connections.", finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "Credential is valid but has no access to any Atlassian connections.", operation_id=op.get("id"))

    # Choose connection to report on
    chosen = None
    if isinstance(connection_id, str):
        for c in accessible:
            if c.get("id") == connection_id:
                chosen = c
                break
        if not chosen:
            op = _append_op("unknown", "failed", http_status=404, error_code="NOT_FOUND",
                            error_message="connection_id not found.", finished_at=_utcnow_iso())
            return _err("NOT_FOUND", "connection_id not found", operation_id=op.get("id"))
    else:
        # default: prefer an active connection if one exists
        for c in accessible:
            if c.get("status") == "active":
                chosen = c
                break
        chosen = chosen or accessible[0]

    # Calculate current rate/concurrency consumption for chosen connection
    ops = _load("tool_operations.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    one_min_ago = now_dt - datetime.timedelta(seconds=60)
    remote_calls_last_min = 0
    running = 0
    for r in ops:
        if not isinstance(r, dict) or r.get("connection_id") != chosen.get("id"):
            continue
        if r.get("status") == "running":
            running += 1
        created_at = r.get("created_at")
        if isinstance(created_at, str):
            try:
                dt = datetime.datetime.fromisoformat(created_at.replace("Z", "+00:00"))
            except Exception:
                dt = None
            if dt and dt.tzinfo and dt >= one_min_ago:
                remote_calls_last_min += 1

    op = _append_op(chosen.get("id"), "succeeded", http_status=200,
                    response_summary={"connections": len(accessible), "chosen_connection_id": chosen.get("id")},
                    finished_at=_utcnow_iso())

    return {
        "operation_id": op.get("id"),
        "caller": {
            "token_present": True,
            "effective_scopes": chosen.get("scopes") if isinstance(chosen.get("scopes"), list) else [],
        },
        "default_connection": {
            "id": chosen.get("id"),
            "org_name": chosen.get("org_name"),
            "site_base_url": chosen.get("site_base_url"),
            "auth_type": chosen.get("auth_type"),
            "status": chosen.get("status"),
        },
        "usage": {
            "connection_id": chosen.get("id"),
            "remote_calls_last_minute": remote_calls_last_min,
            "remote_calls_limit_per_minute": 60,
            "running_operations": running,
            "running_operations_limit": 10,
        },
        "connections": [
            {"id": c.get("id"), "org_name": c.get("org_name"), "site_base_url": c.get("site_base_url"), "status": c.get("status")}
            for c in accessible
        ],
    }

def atlassian_create_connection(authorization, org_name, site_base_url, auth_type, scopes, credentials, **_extra):
    import json, os, datetime, re, urllib.parse, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "atlassian_create_connection"
    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _parse_bearer(h):
        if not isinstance(h, str) or not h.strip():
            return None
        if not h.lower().startswith("bearer "):
            return None
        tok = h.split(" ", 1)[1].strip()
        return tok or None

    def _valid_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _append_op(conn_id_for_log, status, http_status=None, error_code=None, error_message=None,
                   response_summary=None, started_at=None, finished_at=None):
        ops = _load("tool_operations.json")
        now = _utcnow_iso()
        row = {
            "id": _gen_id("op"),
            "connection_id": conn_id_for_log if isinstance(conn_id_for_log, str) else "unknown",
            "tool_name": tool_name,
            "request": {
                "authorization": "Bearer ***",
                "org_name": org_name,
                "site_base_url": site_base_url,
                "auth_type": auth_type,
                "scopes": scopes,
                "credentials_present": credentials is not None,
            },
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": None,
            "affected_entity_type": None,
            "affected_external_ids": None,
            "started_at": started_at or now,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    # Validate authorization format only (no credential table exists in schema)
    if _parse_bearer(authorization) is None:
        op = _append_op("unknown", "failed", http_status=401, error_code="UNAUTHORIZED",
                        error_message="Invalid authorization; expected 'Bearer <token>'.", finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "Invalid authorization; expected 'Bearer <token>'.", operation_id=op.get("id"))

    if not isinstance(org_name, str) or not org_name.strip():
        op = _append_op("unknown", "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="org_name is required.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "org_name is required", operation_id=op.get("id"))
    if not _valid_url(site_base_url):
        op = _append_op("unknown", "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="site_base_url must be a valid URL.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "site_base_url must be a valid URL", operation_id=op.get("id"))
    if auth_type not in ("api_token", "oauth2"):
        op = _append_op("unknown", "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="auth_type must be one of: api_token, oauth2.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "auth_type must be one of: api_token, oauth2", operation_id=op.get("id"))
    if not isinstance(scopes, list) or len(scopes) < 1 or any((not isinstance(s, str) or not s.strip()) for s in scopes):
        op = _append_op("unknown", "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="scopes must be a non-empty array of strings.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "scopes must be a non-empty array of strings", operation_id=op.get("id"))
    if not isinstance(credentials, dict):
        op = _append_op("unknown", "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="credentials is required and must be an object.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "credentials is required and must be an object", operation_id=op.get("id"))
    if auth_type == "api_token":
        api = credentials.get("api_token") if isinstance(credentials, dict) else None
        if not isinstance(api, dict) or not isinstance(api.get("email"), str) or not api.get("email").strip() or not isinstance(api.get("api_token"), str) or not api.get("api_token").strip():
            op = _append_op("unknown", "failed", http_status=400, error_code="VALIDATION_ERROR",
                            error_message="credentials.api_token.email and credentials.api_token.api_token are required.", finished_at=_utcnow_iso())
            return _err("VALIDATION_ERROR", "credentials.api_token.email and credentials.api_token.api_token are required", operation_id=op.get("id"))
    else:
        oa = credentials.get("oauth2") if isinstance(credentials, dict) else None
        if not isinstance(oa, dict) or not isinstance(oa.get("access_token"), str) or not oa.get("access_token").strip():
            op = _append_op("unknown", "failed", http_status=400, error_code="VALIDATION_ERROR",
                            error_message="credentials.oauth2.access_token is required.", finished_at=_utcnow_iso())
            return _err("VALIDATION_ERROR", "credentials.oauth2.access_token is required", operation_id=op.get("id"))

    conns = _load("atlassian_connections.json")
    # Unique(site_base_url, account_id)
    account_id = None
    if isinstance(_extra.get("account_id"), str):
        account_id = _extra.get("account_id")
    # vendor param exists in schema; passed in signature? It's in tool args (account_id param exists in schema but not tool signature)
    # For this tool signature, account_id isn't provided; accept optional in credentials/account context if present
    if isinstance(credentials.get("account_id"), str):
        account_id = credentials.get("account_id")

    for c in conns:
        if not isinstance(c, dict):
            continue
        if c.get("site_base_url") == site_base_url and c.get("account_id") == account_id:
            op = _append_op(c.get("id"), "failed", http_status=409, error_code="CONFLICT",
                            error_message="A connection already exists for this site_base_url and account_id.", finished_at=_utcnow_iso())
            return _err("CONFLICT", "A connection already exists for this site_base_url and account_id", operation_id=op.get("id"))

    now = _utcnow_iso()
    new_id = _gen_id("atl_conn")
    token_ref = "tokref_" + uuid.uuid4().hex[:24].upper()

    row = {
        "id": new_id,
        "org_name": org_name.strip(),
        "site_base_url": site_base_url.strip(),
        "cloud_id": None,
        "auth_type": auth_type,
        "account_id": account_id,
        "scopes": [s.strip() for s in scopes],
        "token_ref": token_ref,
        "status": "active",
        "last_verified_at": now,
        "created_at": now,
        "updated_at": now,
    }
    conns.append(row)
    _save("atlassian_connections.json", conns)

    op = _append_op(new_id, "succeeded", http_status=201,
                    response_summary={"connection_id": new_id, "status": "active"},
                    finished_at=_utcnow_iso())

    return {"operation_id": op.get("id"), "connection": row}

def atlassian_update_connection(authorization, connection_id, org_name=None, site_base_url=None, status=None, scopes=None, credentials=None, **_extra):
    import json, os, datetime, re, urllib.parse, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0101000" if __import__("os").path.isdir("./environment_mix/0101000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "atlassian_update_connection"
    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_bearer(h):
        if not isinstance(h, str) or not h.strip():
            return None
        if not h.lower().startswith("bearer "):
            return None
        tok = h.split(" ", 1)[1].strip()
        return tok or None

    def _valid_url(u):
        if u is None:
            return True
        if not isinstance(u, str) or not u.strip():
            return False
        try:
            p = urllib.parse.urlparse(u.strip())
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _append_op(conn_id_for_log, status_, http_status=None, error_code=None, error_message=None, response_summary=None, started_at=None, finished_at=None):
        ops = _load("tool_operations.json")
        now = _utcnow_iso()
        row = {
            "id": _gen_id("op"),
            "connection_id": conn_id_for_log if isinstance(conn_id_for_log, str) else "unknown",
            "tool_name": tool_name,
            "request": {
                "authorization": "Bearer ***",
                "connection_id": connection_id,
                "org_name": org_name,
                "site_base_url": site_base_url,
                "status": status,
                "scopes": scopes,
                "credentials_present": credentials is not None,
            },
            "status": status_,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "affected_domain": None,
            "affected_entity_type": None,
            "affected_external_ids": None,
            "started_at": started_at or now,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("tool_operations.json", ops)
        return row

    # Auth format only
    if _parse_bearer(authorization) is None:
        op = _append_op(connection_id, "failed", http_status=401, error_code="UNAUTHORIZED",
                        error_message="Invalid authorization; expected 'Bearer <token>'.", finished_at=_utcnow_iso())
        return _err("UNAUTHORIZED", "Invalid authorization; expected 'Bearer <token>'.", operation_id=op.get("id"))

    if not isinstance(connection_id, str) or not re.match(r"^atl_conn_[0-9A-Z]{18,}$", connection_id):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="connection_id is malformed.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "connection_id is malformed", operation_id=op.get("id"))

    if org_name is not None and (not isinstance(org_name, str) or not org_name.strip()):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="org_name must be a non-empty string when provided.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "org_name must be a non-empty string when provided", operation_id=op.get("id"))

    if not _valid_url(site_base_url):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="site_base_url must be a valid URL when provided.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "site_base_url must be a valid URL when provided", operation_id=op.get("id"))

    if status is not None and status not in ("active", "disabled", "revoked", "error"):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="status must be one of: active, disabled, revoked, error.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, revoked, error", operation_id=op.get("id"))

    if scopes is not None:
        if not isinstance(scopes, list) or len(scopes) < 1 or any((not isinstance(s, str) or not s.strip()) for s in scopes):
            op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                            error_message="scopes must be a non-empty array of strings when provided.", finished_at=_utcnow_iso())
            return _err("VALIDATION_ERROR", "scopes must be a non-empty array of strings when provided", operation_id=op.get("id"))

    if credentials is not None and not isinstance(credentials, dict):
        op = _append_op(connection_id, "failed", http_status=400, error_code="VALIDATION_ERROR",
                        error_message="credentials must be an object when provided.", finished_at=_utcnow_iso())
        return _err("VALIDATION_ERROR", "credentials must be an object when provided", operation_id=op.get("id"))

    conns = _load("atlassian_connections.json")
    row = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == connection_id:
            row = c
            break
    if not row:
        op = _append_op(connection_id, "failed", http_status=404, error_code="NOT_FOUND",
                        error_message="connection_id not found.", finished_at=_utcnow_iso())
        return _err("NOT_FOUND", "connection_id not found", operation_id=op.get("id"))

    # Lifecycle transition validation
    if status is not None:
        transitions = {
            "active": ["disabled", "revoked", "error"],
            "disabled": ["active", "revoked", "error"],
            "error": ["active", "disabled", "revoked"],
            "revoked": [],
        }
        cur = row.get("status")
        if cur != status:
            allowed = transitions.get(cur, [])
            if status not in allowed:
                op = _append_op(connection_id, "failed", http_status=409, error_code="INVALID_TRANSITION",
                                error_message=f"Invalid status transition {cur!r} -> {status!r}.", finished_at=_utcnow_iso())
                return _err("INVALID_TRANSITION", f"Invalid status transition {cur!r} -> {status!r}.", operation_id=op.get("id"))

    # Uniqueness check when site_base_url changes: unique(site_base_url, account_id)
    if site_base_url is not None:
        acct = row.get("account_id")
        for c in conns:
            if not isinstance(c, dict) or c.get("id") == connection_id:
                continue
            if c.get("site_base_url") == site_base_url.strip() and c.get("account_id") == acct:
                op = _append_op(connection_id, "failed", http_status=409, error_code="CONFLICT",
                                error_message="unique(site_base_url, account_id) constraint violated.", finished_at=_utcnow_iso())
                return _err("CONFLICT", "unique(site_base_url, account_id) constraint violated", operation_id=op.get("id"))

    op = _append_op(connection_id, "running", started_at=_utcnow_iso())

    now = _utcnow_iso()
    if org_name is not None:
        row["org_name"] = org_name.strip()
    if site_base_url is not None:
        row["site_base_url"] = site_base_url.strip()
    if scopes is not None:
        row["scopes"] = [s.strip() for s in scopes]
        row["last_verified_at"] = now  # emulate verification refresh
    if credentials is not None:
        # emulate credential rotation by updating token_ref and last_verified_at
        row["token_ref"] = "tokref_" + uuid.uuid4().hex[:24].upper()
        row["last_verified_at"] = now
    if status is not None:
        row["status"] = status
        if status == "active":
            row["last_verified_at"] = now
    row["updated_at"] = now

    _save("atlassian_connections.json", conns)

    _finalize_op_id = op.get("id")
    # finalize
    ops = _load("tool_operations.json")
    for r in ops:
        if isinstance(r, dict) and r.get("id") == _finalize_op_id:
            r["status"] = "succeeded"
            r["http_status"] = 200
            r["response_summary"] = {"connection_id": connection_id, "status": row.get("status")}
            r["finished_at"] = _utcnow_iso()
            r["updated_at"] = _utcnow_iso()
            _save("tool_operations.json", ops)
            break

    return {"operation_id": op.get("id"), "connection": row}
